import type { NextConfig } from 'next';

// `next dev` mantém handles abertos em `.next/` via Turbopack.
// `next build` tentava deletar o mesmo dir → EPERM do OneDrive/Windows.
// Solução: dirs separados por lifecycle. Dev nunca bloqueia o output de build.
const isDevMode = process.env.NODE_ENV !== 'production';

const config: NextConfig = {
  // Libera Hot Reload para IPs locais (CORS dev)
  allowedDevOrigins: [ process.env.DEV_HOST || 'localhost' ],

  distDir: isDevMode ? '.next-dev' : '.next-build',

  // Prisma usa binários nativos — não pode ser bundled pelo Turbopack
  serverExternalPackages: [ '@prisma/client', '.prisma/client' ],
  
  turbopack: {},

  webpack ( config ) {
    // SOTA: Habilita a interceptação e carregamento nativo de WebAssembly
    config.experiments = {
      ...config.experiments,
      asyncWebAssembly: true,
      layers: true,
    };
    return config;
  },

  async redirects () {
    return [
      {
        source: '/psicologia',
        destination: '/artigos/psicologia-hs',
        permanent: true,
      },
      {
        source: '/psicologia-hs',
        destination: '/artigos/psicologia-hs',
        permanent: true,
      },
    ];
  },
};

export default config;

/**
 * IDENTITY: Motor de Mapa ICM e Esperanca Matematica
 * PATH: src/lib/perspectiva.ts
 * ROLE: Calcular a matriz de probabilidades posicionais (Mapa ICM via Malmuth-Harville)
 *       e o ganho esperado em equity de torneio de uma acao especifica (Esperanca).
 *       Estende o ICM EV puro ao capturar externalidades: como ganhar/perder um pot
 *       redistribui a equity de TODOS os jogadores, nao apenas do hero.
 * BINDING: [lib/icmEngine.ts, panels/PerspectivePanel.tsx]
 * THEORY: Framework original de Raphael Vitoi (2026).
 *         - Mapa ICM: distribuicao posicional M-H (insumo do motor)
 *         - Esperanca: ganho esperado em equity de uma acao especifica
 *         - Perspectiva Matematica: sintese definitiva (nao implementada — reservada)
 */

// === TIPOS ===

/** Resultado do Mapa ICM: probabilidades posicionais + equities (Malmuth-Harville) */
export interface MapaICMResult {
  /** positionProbs[i][j] = P(jogador i terminar na posicao j) */
  positionProbs: number[][];
  /** Equity ICM de cada jogador (em unidades de premio, nao %) */
  equities: number[];
  /** Total de fichas na mesa */
  totalChips: number;
}

/** Classificacao de tier baseada em stack relativo a media */
export type StackTier = 'micro' | 'short' | 'mid' | 'big' | 'chipleader';

/** Resultado da analise de Esperanca para uma decisao especifica */
export interface EsperancaResult {
  // Estado atual
  currentEquity: number;
  currentEquityPct: number;
  currentMapaICM: number[];
  currentTier: StackTier;

  // Se ganhar
  winEquity: number;
  winEquityPct: number;
  winMapaICM: number[];
  winTier: StackTier;
  deltaWin: number;
  deltaWinPct: number;

  // Se perder
  loseEquity: number;
  loseEquityPct: number;
  loseMapaICM: number[];
  loseTier: StackTier;
  deltaLose: number;
  deltaLosePct: number;

  // Se foldar (Teoria do Fold ICM EV)
  foldEquity: number;
  foldEquityPct: number;
  deltaFold: number;
  survivalValue: number; // Valor intrinseco de manter a stack viva

  /** 
   * Explosao de Valuation (Transfer Efficiency).
   * Raphael Vitoi: 'O valuation de 3bbs pra vc e mt superior ao de qm tem 3x a sua stack'.
   * Ratio entre o ganho de equity do hero por chip e a perda do villain por chip.
   */
  valuationExplosion: number;

  // Esperanca bruta: P(win) x deltaWin + P(lose) x deltaLose
  esperanca: number;
  esperancaPct: number;

  // Perspectiva Realizada: aplica Fator R ao win delta (equity de vitoria e parcialmente realizavel)
  // esperancaRealizada = P(win) x deltaWin x R + P(lose) x deltaLose
  esperancaRealizada: number;
  esperancaRealizadaPct: number;
  realizationFactor: number;

  // ICM EV simples do pot (para comparacao)
  potIcmEv: number;
  potIcmEvPct: number;

  // Externalidade: esperanca - potIcmEv
  externality: number;
  externalityPct: number;

  // Tier shift (win scenario)
  tierShift: boolean;
  tierDirection: 'up' | 'down' | 'none';

  // Tier shift (lose scenario) — risco de degradacao de escalao
  loseTierShift: boolean;
  loseTierDirection: 'down' | 'none';

  // Contexto
  heroName: string;
  villainName: string;
}

// === MAPA ICM (Malmuth-Harville com matriz posicional) ===

/**
 * Calcula a matriz completa de probabilidades posicionais via Malmuth-Harville.
 * Retorna P(jogador i terminar na posicao j) para todos i, j.
 *
 * Complexidade sem memo: O(N!/((N-K)!)) — ~986k calls para N=9.
 * Com isomorfismo interno: O(2^N) estados unicos (~512 para N=9).
 * Com cache externo (modulo): chamadas repetidas com mesmos args = O(1).
 */

// Cache cross-call: evita recomputar M-H para stacks/prizes identicos
// (ex: baseline chamado N vezes dentro da mesma renderizacao).
// LRU simples: descarta entradas mais antigas quando excede MAX_CACHE_SIZE.
const _icmCache = new Map<string, MapaICMResult>();
const _ICM_CACHE_MAX = 128;

function _icmCacheKey(stacks: number[], prizes: number[]): string {
  return `${stacks.join(',')}|${prizes.join(',')}`;
}

export function calculateMapaICM(
  stacks: number[],
  prizes: number[],
): MapaICMResult {
  const n = stacks.length;
  const k = Math.min(prizes.length, n);
  const totalChips = stacks.reduce((s, v) => s + v, 0);

  // Cache cross-call
  const cacheKey = _icmCacheKey(stacks, prizes);
  const hit = _icmCache.get(cacheKey);
  if (hit) return hit;

  // positionProbs[player][position] = probabilidade acumulada
  const positionProbs: number[][] = Array.from({ length: n }, () => new Array(k).fill(0));
  const equities: number[] = new Array(n).fill(0);

  if (totalChips === 0) {
    const result = { positionProbs, equities, totalChips };
    _icmCache.set(cacheKey, result);
    return result;
  }

  // -----------------------------------------------------------------------
  // Isomorfismo via memoizacao: dois subconjuntos com os mesmos indices
  // originais na mesma posicao de premio produzem contribuicoes identicas.
  // Estados unicos: no maximo 2^n = 512 para 9 jogadores, vs ~986k sem memo.
  //
  // Estrutura: posC[player][prize] e eqC[player] sao contribuicoes por
  // unidade de probabilidade (normalizadas). Multiplicar pelo probSoFar
  // do chamador ao acumular no resultado final.
  // -----------------------------------------------------------------------

  type Contrib = { posC: number[][]; eqC: number[] };
  const memo = new Map<string, Contrib>();

  function computeContrib(
    currentStacks: number[],
    originalIndices: number[],
    posIndex: number,
    currentTotal: number,
  ): Contrib {
    if (posIndex >= k || currentStacks.length === 0 || currentTotal === 0) {
      return {
        posC: Array.from({ length: n }, () => new Array(k).fill(0)),
        eqC: new Array(n).fill(0),
      };
    }

    // Chave canonica: indices ordenados (dentro desta chamada os stacks sao
    // fixos, entao indices ordenados determinam univocamente o subconjunto).
    const key = `${posIndex}:${originalIndices.slice().sort((a, b) => a - b).join(',')}`;
    const cached = memo.get(key);
    if (cached) return cached;

    const posC: number[][] = Array.from({ length: n }, () => new Array(k).fill(0));
    const eqC: number[] = new Array(n).fill(0);

    for (let i = 0; i < currentStacks.length; i++) {
      const stack = currentStacks[i];
      if (stack === 0) continue;

      const p = stack / currentTotal;
      const origIdx = originalIndices[i];

      posC[origIdx][posIndex] += p;
      eqC[origIdx] += p * prizes[posIndex];

      const nextStacks = currentStacks.filter((_, j) => j !== i);
      const nextIndices = originalIndices.filter((_, j) => j !== i);
      const sub = computeContrib(nextStacks, nextIndices, posIndex + 1, currentTotal - stack);

      for (let j = 0; j < n; j++) {
        for (let pi = posIndex + 1; pi < k; pi++) {
          posC[j][pi] += p * sub.posC[j][pi];
        }
        eqC[j] += p * sub.eqC[j];
      }
    }

    memo.set(key, { posC, eqC });
    return { posC, eqC };
  }

  const contrib = computeContrib(
    stacks,
    stacks.map((_, i) => i),
    0,
    totalChips,
  );

  for (let j = 0; j < n; j++) {
    for (let pi = 0; pi < k; pi++) {
      positionProbs[j][pi] = contrib.posC[j][pi];
    }
    equities[j] = contrib.eqC[j];
  }

  const result: MapaICMResult = { positionProbs, equities, totalChips };

  // Armazena no cache cross-call; LRU: remove entrada mais antiga se cheio
  if (_icmCache.size >= _ICM_CACHE_MAX) {
    _icmCache.delete(_icmCache.keys().next().value!);
  }
  _icmCache.set(cacheKey, result);

  return result;
}

// === TIER CLASSIFICATION ===

export function classifyTier(stack: number, stacks: number[]): StackTier {
  const avg = stacks.reduce((s, v) => s + v, 0) / stacks.length;
  if (avg === 0) return 'mid';

  const ratio = stack / avg;
  const isLargest = stacks.every(s => stack >= s);

  if (stack === 0) return 'micro';
  if (ratio < 0.4) return 'micro';
  if (ratio < 0.7) return 'short';
  if (ratio < 1.5) return 'mid';
  if (isLargest || ratio >= 2.5) return 'chipleader';
  return 'big';
}

export const TIER_LABELS: Record<StackTier, string> = {
  micro: 'Micro',
  short: 'Short',
  mid: 'Mid',
  big: 'Big',
  chipleader: 'Chip Leader',
};

export const TIER_COLORS: Record<StackTier, string> = {
  micro: '#ff0055',
  short: '#f43f5e',
  mid: '#f59e0b',
  big: '#10b981',
  chipleader: '#6366f1',
};

/** Ordinal numérico de cada tier — usado para comparar escalões sem switch/if */
export const TIER_ORDINAL: Record<StackTier, number> = {
  micro: 0,
  short: 1,
  mid: 2,
  big: 3,
  chipleader: 4,
};

// === ESPERANCA ===

/** Parametros de entrada para calculateEsperanca */
export interface EsperancaInput {
  /** Stacks atuais de todos os jogadores */
  stacks: number[];
  /** Estrutura de premios */
  prizes: number[];
  /** Nomes dos jogadores */
  names: string[];
  /** Indice do hero no array */
  heroIdx: number;
  /** Indice do villain no array */
  villainIdx: number;
  /** Tamanho do pot atual (antes do call do hero) */
  potSize: number;
  /** Quanto o hero arrisca (custo do call/raise) */
  heroCost: number;
  /** Probabilidade do hero ganhar (0-1) */
  winProb: number;
  /** 
   * Aggression Factor (AgrFactor) — Heuristica Raphael Vitoi.
   * Modula o respeito do oponente ao ICM. 
   * < 1.0: Oponente 'over-folds' (respeita demais o RP).
   * > 1.0: Oponente 'under-folds' (ignora o ICM, joga chipEV).
   */
  aggressionFactor?: number;
  /** 
   * Credibilidade da Informacao (0.0 - 1.0).
   * Raphael Vitoi: 'O tamanho do seu desvio tem q ser proporcional a credibilidade da sua informacao'.
   */
  credibility?: number;
  /** 
   * Distancia do e-Nash (Oponente Gap). 
   * Mede o quanto o oponente desvia da agressao teoria (ex: cbet-fold turn alto).
   */
  opponentGap?: number;
  /**
   * Fator de Realizacao de Equidade (R). Quanto da equity bruta de vitoria o hero
   * efetivamente captura. HU ≈ 1.0; multiway cai com o numero de oponentes.
   * Default: 1.0. Faixa tipica: 0.6-1.0.
   */
  realizationFactor?: number;
}

/**
 * Calcula a Agressividade Teorica esperada para um spot (Baseado na Aula 1.2).
 * Define quanto o atacante 'deveria' pressionar o defensor baseado no ICM.
 * @param attackerTier Tier de quem tem a iniciativa (Villain)
 * @param defenderTier Tier de quem defende (Hero)
 */
export function calculateTheoreticalAggression(attackerTier: StackTier, defenderTier: StackTier): number {
  const attackerVal = TIER_ORDINAL[attackerTier];
  const defenderVal = TIER_ORDINAL[defenderTier];
  const diff = attackerVal - defenderVal;

  // CL atacando Short/Micro: Pressao ICM Maxima (Aula 1.2: Over-bluffing justified)
  if (attackerTier === 'chipleader' && defenderVal <= 1) return 1.4;
  
  // Big atacando Mid: Pressao Significativa
  if (attackerVal > defenderVal && diff >= 1) return 1.2;

  // Confronto Simetrico: GTO puro
  if (attackerVal === defenderVal) return 1.0;

  // Short atacando Big/CL: Agressividade Contida (Fear of elimination)
  if (attackerVal < defenderVal) return 0.8;

  return 1.0;
}

/**
 * Calcula a Esperanca Matematica de uma decisao (call/raise/fold).
 */
export function calculateEsperanca({
  stacks,
  prizes,
  names,
  heroIdx,
  villainIdx,
  potSize,
  heroCost,
  winProb,
  aggressionFactor = 1.0,
  realizationFactor = 1,
}: EsperancaInput): EsperancaResult {
  const totalPrizes = prizes.reduce((s, v) => s + v, 0);

  const current = calculateMapaICM(stacks, prizes);
  const currentEquity = current.equities[heroIdx];
  const villainCurrentEquity = current.equities[villainIdx];
  const currentEquityPct = totalPrizes > 0 ? (currentEquity / totalPrizes) * 100 : 0;
  const currentTier = classifyTier(stacks[heroIdx], stacks);
  const villainTier = classifyTier(stacks[villainIdx], stacks);

  // SOTA: Agressividade Teorica (Aula 1.2) + Fator Humano
  const theoreticalBase = calculateTheoreticalAggression(villainTier, currentTier);
  const finalAggression = theoreticalBase * aggressionFactor;

  // Ajuste de WinProb baseado no perfil de agressao do vilao
  const adjustedWinProb = Math.max(0, Math.min(1, winProb / finalAggression));

  // 2. Cenarios pos-decisao
  const stacksAfterWin = stacks.map((s, i) => {
    if (i === heroIdx) return s + potSize; // hero wins pot
    return s;
  });

  const stacksAfterLose = stacks.map((s, i) => {
    if (i === heroIdx) return Math.max(0, s - heroCost); // hero loses call
    if (i === villainIdx) return s + potSize + heroCost; // villain wins pot + hero's call
    return s;
  });

  const perspWin = calculateMapaICM(stacksAfterWin, prizes);
  const perspLose = calculateMapaICM(stacksAfterLose, prizes);

  const winEquity = perspWin.equities[heroIdx];
  const loseEquity = perspLose.equities[heroIdx];
  const winEquityPct = totalPrizes > 0 ? (winEquity / totalPrizes) * 100 : 0;
  const loseEquityPct = totalPrizes > 0 ? (loseEquity / totalPrizes) * 100 : 0;

  // Calculo da perda do Villain para medir a Explosao (Transfer Efficiency)
  const villainLoseEquity = perspWin.equities[villainIdx];
  const villainDeltaLoss = villainCurrentEquity - villainLoseEquity;

  const deltaWin = winEquity - currentEquity;
  const deltaLose = loseEquity - currentEquity;
  const deltaWinPct = winEquityPct - currentEquityPct;
  const deltaLosePct = loseEquityPct - currentEquityPct;

  // SOTA: Explosao de Valuation
  const valuationExplosion = villainDeltaLoss > 0 ? deltaWin / villainDeltaLoss : 1.0;

  // Esperanca final usando a probabilidade ajustada pelo Perfil de Agressao
  const esperanca = adjustedWinProb * deltaWin + (1 - adjustedWinProb) * deltaLose;
  const esperancaPct = adjustedWinProb * deltaWinPct + (1 - adjustedWinProb) * deltaLosePct;

  // Perspectiva Realizada
  const R = Math.max(0, Math.min(1, realizationFactor));
  const esperancaRealizada = adjustedWinProb * deltaWin * R + (1 - adjustedWinProb) * deltaLose;
  const esperancaRealizadaPct = adjustedWinProb * deltaWinPct * R + (1 - adjustedWinProb) * deltaLosePct;

  // Metricas de comparacao simplificadas
  const chipValuePerUnit = totalPrizes / current.totalChips;
  const potIcmEv = adjustedWinProb * potSize * chipValuePerUnit - (1 - adjustedWinProb) * heroCost * chipValuePerUnit;
  const potIcmEvPct = totalPrizes > 0 ? (potIcmEv / totalPrizes) * 100 : 0;

  const externality = esperanca - potIcmEv;
  const externalityPct = esperancaPct - potIcmEvPct;

  const winTier = classifyTier(stacksAfterWin[heroIdx], stacksAfterWin);
  const loseTier = classifyTier(stacksAfterLose[heroIdx], stacksAfterLose);

  // 3. Calculo do Fold ICM EV (Teoria Raphael Vitoi)
  const foldData = calculateEsperancaFold(stacks, prizes, names, heroIdx, villainIdx, potSize);

  const tierShift = winTier !== currentTier;
  let tierDirection: 'up' | 'down' | 'none';
  if (TIER_ORDINAL[winTier] > TIER_ORDINAL[currentTier]) {
    tierDirection = 'up';
  } else if (TIER_ORDINAL[winTier] < TIER_ORDINAL[currentTier]) {
    tierDirection = 'down';
  } else {
    tierDirection = 'none';
  }

  return {
    currentEquity, currentEquityPct, currentMapaICM: current.positionProbs[heroIdx], currentTier,
    winEquity, winEquityPct, winMapaICM: perspWin.positionProbs[heroIdx], winTier,
    deltaWin, deltaWinPct,
    loseEquity, loseEquityPct, loseMapaICM: perspLose.positionProbs[heroIdx], loseTier,
    deltaLose, deltaLosePct,
    foldEquity: foldData.winEquity, foldEquityPct: foldData.winEquityPct, deltaFold: foldData.esperanca, survivalValue: foldData.survivalValue,
    valuationExplosion,
    esperanca, esperancaPct,
    esperancaRealizada, esperancaRealizadaPct, realizationFactor: R,
    potIcmEv, potIcmEvPct,
    externality, externalityPct,
    tierShift, tierDirection,
    loseTierShift: loseTier !== currentTier,
    loseTierDirection: TIER_ORDINAL[loseTier] < TIER_ORDINAL[currentTier] ? 'down' : 'none',
    heroName: names[heroIdx] ?? `Jogador ${heroIdx + 1}`,
    villainName: names[villainIdx] ?? `Jogador ${villainIdx + 1}`,
  };
}

/**
 * Calcula Esperanca de FOLD (para comparacao com call).
 * No fold, hero mantem stack atual. Pot vai para villain.
 */
export function calculateEsperancaFold(
  stacks: number[],
  prizes: number[],
  names: string[],
  heroIdx: number,
  villainIdx: number,
  potSize: number,
): Pick<EsperancaResult, 'esperanca' | 'esperancaPct' | 'winEquity' | 'winEquityPct' | 'survivalValue'> {
  const totalPrizes = prizes.reduce((s, v) => s + v, 0);

  // Fold: hero mantem stack, villain leva pot
  const stacksAfterFold = stacks.map((s, i) => {
    if (i === villainIdx) return s + potSize;
    return s;
  });

  const perspFold = calculateMapaICM(stacksAfterFold, prizes);
  const foldEquity = perspFold.equities[heroIdx];
  const foldEquityPct = totalPrizes > 0 ? (foldEquity / totalPrizes) * 100 : 0;

  const current = calculateMapaICM(stacks, prizes);
  const currentEquity = current.equities[heroIdx];
  const currentEquityPct = totalPrizes > 0 ? (currentEquity / totalPrizes) * 100 : 0;

  // Calculo de SurvivalValue: a probabilidade de sobrevivencia passiva (sem colidir)
  // No ICM, o Fold é um ativo defensivo que preserva o tier.
  // Se deltaFold for menos negativo que o custo do call, o Fold ganha "valor de utilidade".
  const survivalValue = foldEquity / currentEquity; // Ratio de manutencao de equidade

  return {
    esperanca: foldEquity - currentEquity,
    esperancaPct: foldEquityPct - currentEquityPct,
    winEquity: foldEquity,
    winEquityPct: foldEquityPct,
    survivalValue: survivalValue
  };
}

edit:
 * IDENTITY: Motor de Perspectiva Matemática SOTA v4.0 (VITOI - QUANTUM)
 * PATH: src/lib/perspectiva.ts
 * ROLE: Core algorítmico da Equação Unificada SOTA.
 *       PM = [(Equity * R) * Valuation] - [EV_fold(t, dpj, pos) + RIO_mw]
 */

import { calculateIcmMonteCarlo } from './montecarlo';

// === TIPOS E INTERFACES ===

export interface MapaICMResult {
  positionProbs: number[][];
  equities: number[];
  totalChips: number;
}

export type StackTier = 'micro' | 'short' | 'mid' | 'big' | 'chipleader';

export interface PerspectivaResult {
  // Layer 1: ICMev (Snapshot)
  currentEquityPct: number;
  deltaWinPct: number;
  deltaLosePct: number;
  deltaFoldPct: number;

  // Layer 2: Esperança (Lógica)
  valuation: number; // Coeficiente de explosão financeira das fichas
  rioLiability: number; // Dívida matemática por multiway/RIO

  // Layer 3: Expectativa (Preditiva)
  fgsHealth: number;
  survivalPressure: number;
  dynamicEvFold: number; // O piso real (pode ser positivo via laddering)

  // Layer 4: Perspectiva (A Síntese Final)
  perspectivaPct: number; // PM Final
  amortizedEdge: number;
  ci: number; // Coeficiente de Insolvência (PM / PotOdds)
  marginInstability: number; // Incerteza % baseada no stack efetivo

  // Metadados
  isActionBetterThanFold: boolean;
  diagnostico: string;
  bountyPower?: number;

  // Detalhes posicionais (M-H)
  currentMapaICM: number[];
  winMapaICM: number[];
  loseMapaICM: number[];
}

export interface PerspectivaInput {
  stacks: number[];
  prizes: number[];
  heroIdx: number;
  villainIdx: number;
  potSize: number;
  heroCost: number;
  winProb: number;
  realizationFactor: number; // R
  edgeBase: number;
  bountyValue?: number; // PKO
  kappa?: number; // Axioma Lipe Piv (Credibilidade da Informacao)

  // Parâmetros Quantum (v4.0)
  numPlayersInPot?: number; // Para RIO_mw
  isNearPayjump?: boolean;  // Para EV_fold positivo
  blindsRisingSoon?: boolean; // Para Erosão de stack
  currentEquityPct?: number; // Para Delta Fold Pct

  // Parametros Opcionais de Teoremas
  spr?: number;
  investidoAcumulado?: number;
  blindCost?: number;
}

// === MOTOR ICM (Malmuth-Harville / Monte Carlo Estocástico) ===
const _icmCache = new Map<string, MapaICMResult>();

export function calculateMapaICM ( stacks: number[], prizes: number[] ): MapaICMResult {
  const n = stacks.length;

  // SOTA: Monte Carlo Fallback para evitar explosão combinatória (O(2^N))
  // Adaptado de bibliotecas Open Source para fields maiores
  if ( n > 10 )
  {
    const totalChips = stacks.reduce( ( s, v ) => s + v, 0 );
    const equities = calculateIcmMonteCarlo(stacks, prizes, { iterations: 20000 });
    
    // Probs aproximadas (não totalmente precisas via MCMC, mas suficientes para fallback)
    const positionProbs = Array.from( { length: n }, () => new Array( Math.min( n, prizes.length ) ).fill( 0 ) );
    const totalPrize = prizes.reduce( ( s, v ) => s + v, 0 );
    
    if ( totalChips > 0 && prizes.length > 0 ) {
      stacks.forEach( ( s, i ) => {
          positionProbs[ i ][ 0 ] = s / totalChips;
          // As outras posições não são estritamente necessárias para a síntese final do EV monetário 
          // neste fallback aproximado, apenas a Equidade importa.
      });
    }
    return { positionProbs, equities, totalChips };
  }

  // SOTA: Normaliza o array de prêmios para o tamanho da mesa
  const activePrizes = prizes.slice( 0, n );
  const k = activePrizes.length;
  const totalChips = stacks.reduce( ( s, v ) => s + v, 0 );
  const key = `${stacks.join( ',' )}|${activePrizes.join( ',' )}`;

  const cachedIcm = _icmCache.get( key );
  if ( cachedIcm ) return cachedIcm;

  const positionProbs: number[][] = Array.from( { length: n }, () => new Array( k ).fill( 0 ) );
  const equities: number[] = new Array( n ).fill( 0 );

  if ( totalChips === 0 || k === 0 ) return { positionProbs, equities, totalChips };

  const memo = new Map<string, { posC: number[][]; eqC: number[] }>();

  function compute ( currStacks: number[], currIndices: number[], posIdx: number, currTotal: number ): { posC: number[][]; eqC: number[] } {
    if ( posIdx >= k || currStacks.length === 0 || currTotal === 0 )
    {
      return { posC: Array.from( { length: n }, () => new Array( k ).fill( 0 ) ), eqC: new Array( n ).fill( 0 ) };
    }

    const stateKey = `${posIdx}:${currIndices.slice().sort( ( a, b ) => a - b ).join( ',' )}`;
    const cachedState = memo.get( stateKey );
    if ( cachedState ) return cachedState;

    const posC: number[][] = Array.from( { length: n }, () => new Array( k ).fill( 0 ) );
    const eqC: number[] = new Array( n ).fill( 0 );

    for ( let i = 0; i < currStacks.length; i++ )
    {
      const stack = currStacks[ i ];
      if ( stack <= 0 ) continue;
      const p = stack / currTotal;
      const origIdx = currIndices[ i ];

      posC[ origIdx ][ posIdx ] += p;
      eqC[ origIdx ] += p * activePrizes[ posIdx ];

      const sub = compute( currStacks.filter( ( _, j ) => j !== i ), currIndices.filter( ( _, j ) => j !== i ), posIdx + 1, currTotal - stack );
      for ( let j = 0; j < n; j++ )
      {
        for ( let pi = posIdx + 1; pi < k; pi++ ) posC[ j ][ pi ] += p * sub.posC[ j ][ pi ];
        eqC[ j ] += p * sub.eqC[ j ];
      }
    }
    const res = { posC, eqC };
    memo.set( stateKey, res );
    return res;
  }

  const resultContrib = compute( stacks, stacks.map( ( _, i ) => i ), 0, totalChips );
  const finalResult = { positionProbs: resultContrib.posC, equities: resultContrib.eqC, totalChips };
  _icmCache.set( key, finalResult );
  return finalResult;
}

export function classifyTier ( stack: number, stacks: number[] ): StackTier {
  const avg = ( stacks.reduce( ( s, v ) => s + v, 0 ) / stacks.length ) || 1;
  const ratio = stack / avg;
  if ( stack <= 0 || ratio < 0.4 ) return 'micro';
  if ( ratio < 0.7 ) return 'short';
  if ( ratio < 1.5 ) return 'mid';
  if ( stacks.every( s => stack >= s ) || ratio >= 2.5 ) return 'chipleader';
  return 'big';
}

// --- HELPERS DE REDUÇÃO DE ENTROPIA COGNITIVA (SOTA V4.0) ---

function _buildSimulatedStacks ( stacks: number[], heroIdx: number, villainIdx: number, potSize: number, heroCost: number ) {
  const stacksWin = stacks.map( ( s, i ) => ( i === heroIdx ? s + potSize : s ) );
  const stacksLose = stacks.map( ( s, i ) => {
    if ( i === heroIdx ) return Math.max( 0, s - heroCost );
    if ( i === villainIdx ) return s + potSize + heroCost;
    return s;
  } );
  const stacksFold = stacks.map( ( s, i ) => {
    if ( i === heroIdx ) return Math.max( 0, s - heroCost );
    if ( i === villainIdx ) return s + potSize;
    return s;
  } );
  return { stacksWin, stacksLose, stacksFold };
}

function _calculateSnapshot ( input: PerspectivaInput, totalPrizes: number ) {
  const { stacks, prizes, heroIdx, villainIdx, potSize, heroCost, bountyValue = 0 } = input;
  const current = calculateMapaICM( stacks, prizes );
  const currentEquityPct = ( current.equities[ heroIdx ] / totalPrizes ) * 100;
  const { stacksWin, stacksLose, stacksFold } = _buildSimulatedStacks( stacks, heroIdx, villainIdx, potSize, heroCost );
  const perspWin = calculateMapaICM( stacksWin, prizes );
  const perspLose = calculateMapaICM( stacksLose, prizes );
  const perspFold = calculateMapaICM( stacksFold, prizes );

  return {
    current,
    currentEquityPct,
    stacksWin,
    deltaWinPct: ( ( perspWin.equities[ heroIdx ] / totalPrizes ) * 100 + bountyValue ) - currentEquityPct,
    deltaLosePct: ( ( perspLose.equities[ heroIdx ] / totalPrizes ) * 100 ) - currentEquityPct,
    deltaFoldPct: ( ( perspFold.equities[ heroIdx ] / totalPrizes ) * 100 ) - currentEquityPct,
    perspWin,
    perspLose
  };
}

function _calculateValuationAndRio ( current: MapaICMResult, deltaWinPct: number, perspWin: MapaICMResult, villainIdx: number, totalPrizes: number, potSize: number, numPlayersInPot: number ) {
  const villainDeltaLoss = current.equities[ villainIdx ] - perspWin.equities[ villainIdx ];
  const rawValuation = villainDeltaLoss > 0 ? deltaWinPct / ( ( villainDeltaLoss / totalPrizes ) * 100 ) : 1;
  const valuation = Math.max( 0.1, Math.min( 2, rawValuation ) );

  // SOTA: Alinhamento Dimensional. Converte o RIO em Fichas para RIO em ICM Equity (Impacto Real).
  const rioPenaltyChips = numPlayersInPot > 2 ? potSize * ( 1 + Math.log2( numPlayersInPot - 1 ) ) * 0.15 : 0;
  const icmPerChip = current.equities[ villainIdx ] > 0 ? ( ( current.equities[ villainIdx ] / totalPrizes ) * 100 ) / ( current.totalChips / numPlayersInPot ) : 0; // Proxy de conversao
  const rioLiability = rioPenaltyChips * ( icmPerChip || 0.01 );

  return { valuation, rioLiability };
}

function _calculateFoldPressure ( input: PerspectivaInput, stacksWin: number[], deltaFoldPct: number ) {
  const { prizes, heroIdx, stacks, isNearPayjump = false, blindsRisingSoon = false, currentEquityPct = 0 } = input; // Contexto estendido
  const stackHero = stacks[ heroIdx ];
  const isVacuum = prizes.length <= 1;
  const handsToBust = Math.max( 1, stackHero / 1.5 );
  const survivalPressure = isVacuum ? 0 : Math.min( 1, 1 / handsToBust );
  const currentTier = classifyTier( stackHero, stacks );
  const winTier = classifyTier( stacksWin[ heroIdx ], stacksWin );
  const tierBonus = isVacuum || winTier === currentTier ? 0 : 0.15;
  const fgsHealth = isVacuum ? 1 : ( 1 + tierBonus + ( survivalPressure * 0.2 ) );
  const payjumpBonus = ( isNearPayjump && !isVacuum ) ? Math.max( 1.2, Math.abs( deltaFoldPct ) + 0.25 ) : 0;

  // SOTA: Erosão Proporcional (Decaimento não ultrapassa o limite zero de equity)
  const erosionPenalty = ( blindsRisingSoon && !isVacuum ) ? Math.abs( deltaFoldPct * 0.5 ) + 0.1 : 0;

  return {
    isVacuum,
    survivalPressure,
    fgsHealth,
    payjumpBonus,
    dynamicEvFold: deltaFoldPct + payjumpBonus - erosionPenalty
  };
}

function _resolveRealizationFactor ( input: PerspectivaInput, stackHero: number, stackVillain: number, potSize: number, numPlayersInPot: number ) {
  const effectiveStack = Math.min( stackHero, stackVillain );
  const spr = input.spr ?? ( effectiveStack / ( potSize || 1 ) );
  let R = input.realizationFactor;

  if ( input.realizationFactor === 1 && numPlayersInPot === 2 )
  {
    const isHeroOop = input.realizationFactor < 1 || ( input.realizationFactor === 1 && input.heroIdx > input.villainIdx );
    if ( isHeroOop )
    {
      const oopPenalty = 0.25 * ( 1 - Math.exp( -spr / 2 ) );
      R = Math.max( 0.75, 1 - oopPenalty );
    }
  }

  return { R, effectiveStack };
}

function _calculateAmortizedEdge ( input: PerspectivaInput, stackHero: number, stackVillain: number, isVacuum: boolean, survivalPressure: number ) {
  const isVillainShort = stackVillain < 12;
  const ratio = stackHero / ( stackVillain || 1 );
  const edgePenalty = ( !isVacuum && isVillainShort && ratio > 3 ) ? 0.3 : 1;
  const effectiveStackForEdge = input.spr === undefined ? stackHero : Math.max( 2, input.spr * 5 );
  const edgeScale = effectiveStackForEdge > 15
    ? Math.log10( effectiveStackForEdge ) / Math.log10( 60 )
    : 0.4 + ( survivalPressure * 0.2 );

  return { edgePenalty, amortizedEdge: input.edgeBase * edgePenalty * edgeScale };
}

function _buildDiagnostico ( perspectivaPct: number, rioLiability: number, payjumpBonus: number, edgePenalty: number, investidoAcumulado: number | undefined, stackHero: number, kappa: number ): string {
  let diagnostico = perspectivaPct > 0 ? "Ação Soberana." : "Insolvência de Perspectiva.";
  if ( rioLiability > 1 ) diagnostico += " Alerta: Colapso Multiway.";
  if ( payjumpBonus > 0 ) diagnostico += " Laddering favorece o Fold.";
  if ( edgePenalty < 1 ) diagnostico += " Punição: Restaurando árvore do oponente.";
  if ( investidoAcumulado && investidoAcumulado > ( stackHero * 0.3 ) ) diagnostico += " Alerta: Pot Entrapment Severo.";
  if ( Math.abs( perspectivaPct ) <= 5 && kappa < 0.4 ) diagnostico += " Credibilidade Baixa: Intuição filtrada pelo Baseline Matemático.";
  return diagnostico;
}

// === A EQUAÇÃO UNIFICADA SOTA ===

export function calculatePerspectivaVitoi ( input: PerspectivaInput ): PerspectivaResult {
  const {
    stacks, prizes, heroIdx, villainIdx, potSize, heroCost,
    winProb, numPlayersInPot = 2,
    isNearPayjump = false, blindsRisingSoon = false,
    kappa = 0.5
  } = input;

  const totalPrizes = prizes.reduce( ( s, v ) => s + v, 0 );
  const stackHero = stacks[ heroIdx ];
  const stackVillain = stacks[ villainIdx ];

  const {
    current,
    currentEquityPct,
    stacksWin,
    deltaWinPct,
    deltaLosePct,
    deltaFoldPct,
    perspWin,
    perspLose
  } = _calculateSnapshot( input, totalPrizes );
  const { valuation, rioLiability } = _calculateValuationAndRio( current, deltaWinPct, perspWin, villainIdx, totalPrizes, potSize, numPlayersInPot );
  const { isVacuum, survivalPressure, fgsHealth, payjumpBonus, dynamicEvFold } = _calculateFoldPressure( input, stacksWin, deltaFoldPct );
  const { R } = _resolveRealizationFactor( input, stackHero, stackVillain, potSize, numPlayersInPot );
  const { edgePenalty, amortizedEdge } = _calculateAmortizedEdge( input, stackHero, stackVillain, isVacuum, survivalPressure );

  // Axioma Lipe Piv: Regressão Bayesiana da Equidade
  const baselineEquity = heroCost / ( potSize + heroCost );
  const bayesianWinProb = baselineEquity + kappa * ( winProb - baselineEquity );

  // A EQUAÇÃO UNIFICADA: PM = [(Equity * R) * Valuation] - [EV_fold + RIO_mw]
  // Aqui adaptada para os Deltas calculados. Valuation atua apenas sobre o ganho (evitando dupla contagem):
  const expectativaReal = ( bayesianWinProb * deltaWinPct * R * valuation * fgsHealth ) + ( ( 1 - bayesianWinProb ) * deltaLosePct );
  const perspectivaPct = ( expectativaReal * amortizedEdge ) - ( dynamicEvFold + rioLiability );

  const potOddsPct = ( potSize / ( potSize + heroCost ) ) * 100;
  const ci = perspectivaPct / ( potOddsPct || 1 );

  // SOTA: Instabilidade de EVs (Mutação da Margem)
  const effectiveStack = Math.min( stackHero, stackVillain );
  const marginInstability = Math.max(0.01, 1 / Math.max(2, effectiveStack)) * 100;

  // Diagnóstico
  const diagnostico = _buildDiagnostico( perspectivaPct, rioLiability, payjumpBonus, edgePenalty, input.investidoAcumulado, stackHero, kappa );

  return {
    currentEquityPct, deltaWinPct, deltaLosePct, deltaFoldPct,
    valuation, rioLiability,
    fgsHealth, survivalPressure, dynamicEvFold,
    perspectivaPct, amortizedEdge, ci, marginInstability,
    isActionBetterThanFold: perspectivaPct > 0,
    diagnostico,
    currentMapaICM: current.positionProbs[ heroIdx ],
    winMapaICM: perspWin.positionProbs[ heroIdx ],
    loseMapaICM: perspLose.positionProbs[ heroIdx ]
  };
}

// === FÍSICA BASE DO POKER (FATOR DE APRISIONAMENTO SOTA) ===

export function calculateRioTension (
  heroInvested: number,
  currentPot: number,
  heroRawStack: number,
  heroPosition: 'IP' | 'OOP',
  baseRioLiability: number,
  mitigationFactor: number = 1
): number {
  const betToCall = currentPot * 0.5;
  const potEntrapment = ( heroInvested + betToCall ) / Math.max( 0.1, heroRawStack );
  const downwardDrift = heroPosition === 'OOP' ? 1.25 : 0.85;

  return Math.min( 1, ( baseRioLiability / 100 ) + ( potEntrapment * downwardDrift * mitigationFactor ) );
}

// === PROSPECT THEORY (KAHNEMAN & TVERSKY) ===

export type ReferencePointStatus = 'baseline' | 'tilt' | 'protecting' | 'bubble';

/**
 * Aplica a Curva de Utilidade (Value Function) da Teoria do Prospecto.
 * Ganhos são côncavos (retorno marginal decrescente).
 * Perdas são convexas e mais inclinadas (Loss Aversion).
 */
export function calculateUtilityEV(
  rawEv: number, 
  status: ReferencePointStatus = 'baseline',
  lossAversionBase: number = 2.25
): number {
  let lambda = lossAversionBase; // Multiplicador de aversão à perda
  let alpha = 0.88; // Concavidade de ganhos
  let beta = 0.88; // Convexidade de perdas

  // O "Reference Point" altera o quão intensa é a dor da perda ou a busca pelo risco
  switch (status) {
    case 'tilt':
      // "Stuck" (perdendo): Busca o risco. A dor adicional diminui, e a aversão à perda cai (chasing losses)
      lambda = 1.5; 
      beta = 0.95; // Mais próximo da linearidade nas perdas
      break;
    case 'protecting':
      // Acima do Buy-in: Protegendo o lucro. Extrema aversão à perda.
      lambda = 3.0; 
      alpha = 0.75; // Ganhos adicionais valem muito menos
      break;
    case 'bubble':
      // Sobrevivência extrema: O valor da ficha perdida é astronômico
      lambda = 4.5;
      break;
    case 'baseline':
    default:
      break;
  }

  if (rawEv >= 0) {
    // Área de Ganhos
    return Math.pow(rawEv, alpha);
  } else {
    // Área de Perdas
    return -lambda * Math.pow(Math.abs(rawEv), beta);
  }

