/**
 * IDENTITY: Dashboard de Perspectiva Matemática SOTA v4.0 (VITOI - QUANTUM)
 * PATH: src/components/simulator/panels/PerspectivePanel.tsx
 * ROLE: Visualização da Física Quântica do Poker: Piso Dinâmico, RIO Exponencial e Valuation.
 */

import { MetricTooltip } from '@/app/ICMlaboratory/RiskPremiumDashboard';
import type React from 'react';
import { useMemo, useState } from 'react';
import {
  CartesianGrid,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  calculatePerspectivaVitoi
} from '../../../lib/perspectiva';
import styles from '../simulator.module.css';

// === ESTILOS ===
const PANEL_STYLE: React.CSSProperties = { display: 'flex', flexDirection: 'column', gap: '1.8rem', padding: '2rem' };
const LAYER_STEP: React.CSSProperties = {
  padding: '1.25rem 1.5rem',
  borderRadius: '12px',
  borderLeft: '4px solid var(--accent-indigo)',
  background: 'rgba(15,23,42,0.4)',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  boxShadow: '0 4px 20px rgba(0,0,0,0.2)',
  transition: 'all 0.3s ease'
};

const INITIAL_CHART_DIMENSION = { width: 1, height: 1 };

interface PerspectivePanelProps {
  initialStacks?: number[];
  initialPrizes?: number[];
  anteSize?: number;
  heroInvestedBb?: number;
  currentPotBb?: number;
}

export default function PerspectivePanel ( { initialStacks, initialPrizes, anteSize = 12.5, heroInvestedBb = 1, currentPotBb = 2.5 }: Readonly<PerspectivePanelProps> ) {
  const stacks = useMemo( () => initialStacks ?? [ 9.4, 52.4, 22.2, 7, 44.3, 24.3, 40, 13.4, 55 ], [ initialStacks ] );
  const prizes = useMemo( () => initialPrizes ?? [ 237.34, 170.96, 135.17, 109.99, 90.28, 73.95, 59.92, 47.56, 36.47 ], [ initialPrizes ] );

  // --- ESTADO DO SIMULADOR (Quantum v4.0) ---
  const [ winProb, setWinProb ] = useState( 0.55 );
  const [ realization, setRealization ] = useState( 1 );
  const edgeBase = 1.2;
  const [ bountyValue, setBountyValue ] = useState( 0 );
  const [ numPlayers, setNumPlayers ] = useState( 2 );
  const [ isNearPayjump, setIsNearPayjump ] = useState( false );
  const [ blindsRising, setBlindsRising ] = useState( false );
  const [ kappa, setKappa ] = useState( 0.5 ); // Nível de Credibilidade (Axioma Lipe Piv)

  // SOTA: O Sunk Cost e Pot Size herdam da arvore global para unificar a termodinamica.
  const potSize = currentPotBb;
  const foldEvBb = useMemo( () => -( Math.abs( heroInvestedBb ) + ( anteSize / 100 ) ), [ heroInvestedBb, anteSize ] );
  const heroCost = Math.abs( foldEvBb );

  const result = useMemo( () => {
    return calculatePerspectivaVitoi( {
      stacks, prizes,
      heroIdx: 0, villainIdx: 1,
      potSize, heroCost, winProb,
      realizationFactor: realization,
      edgeBase,
      bountyValue,
      kappa,
      numPlayersInPot: numPlayers,
      isNearPayjump,
      blindsRisingSoon: blindsRising
    } );
  }, [ stacks, prizes, potSize, heroCost, winProb, realization, edgeBase, bountyValue, kappa, numPlayers, isNearPayjump, blindsRising ] );

  // --- DATA GEN ---
  const chartData = useMemo( () => {
    const points = [];
    for ( let p = 0; p <= 100; p += 5 )
    {
      const pDecimal = p / 100;
      const r = calculatePerspectivaVitoi( {
        stacks, prizes, heroIdx: 0, villainIdx: 1,
        potSize, heroCost, winProb: pDecimal,
        realizationFactor: realization, edgeBase, bountyValue, kappa,
        numPlayersInPot: numPlayers, isNearPayjump, blindsRisingSoon: blindsRising
      } );
      points.push( { name: `${p}%`, prob: p, "PM Quantum": r.perspectivaPct } );
    }
    return points;
  }, [ stacks, prizes, potSize, heroCost, realization, edgeBase, bountyValue, kappa, numPlayers, isNearPayjump, blindsRising ] );

  // SOTA: Render Shield para o Gráfico (Economia Generalizada)
  // Evita o re-render catastrófico do Recharts quando o slider 'winProb' (Equity) é deslizado.
  const chartElement = useMemo( () => (
    <ResponsiveContainer width="100%" height="100%" minWidth={ 1 } minHeight={ 1 } initialDimension={ INITIAL_CHART_DIMENSION }>
      <LineChart data={ chartData }>
        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={ false } />
        <XAxis dataKey="name" fontSize={ 8 } tick={ { fill: '#475569' } } axisLine={ false } tickLine={ false } />
        <YAxis fontSize={ 8 } tick={ { fill: '#475569' } } axisLine={ false } tickLine={ false } tickFormatter={ ( v ) => `${v.toFixed( 0 )}%` } />
        <Tooltip contentStyle={ { background: 'var(--bg-panel)', border: '1px solid rgba(255,255,255,0.1)', fontSize: '0.6rem', borderRadius: '8px' } } />
        <ReferenceLine y={ 0 } stroke="#475569" strokeDasharray="3 3" />
        <Line type="monotone" dataKey="PM Quantum" stroke="#818cf8" strokeWidth={ 2.5 } dot={ false } />
      </LineChart>
    </ResponsiveContainer>
  ), [ chartData ] );

  return (
    <div className={ styles.glassPanel } style={ PANEL_STYLE }>
      <div style={ { borderBottom: '1px solid rgba(255,255,255,0.05)', paddingBottom: '1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' } }>
        <div>
          <h3 style={ { margin: 0, fontSize: '0.85rem', fontWeight: 900, color: 'var(--accent-indigo-light)', textTransform: 'uppercase', letterSpacing: '0.15em' } }>
            Perspectiva Matemática &middot; v4.0 Quantum
          </h3>
          <p style={ { margin: '0.35rem 0 0', fontSize: '0.7rem', color: 'var(--text-dim)' } }>
            Física da Decisão: Piso Dinâmico e Dívida RIO
          </p>
        </div>
        <div style={ { fontSize: '0.65rem', fontWeight: 800, background: isNearPayjump ? 'rgba(16,185,129,0.1)' : 'transparent', padding: '6px 12px', borderRadius: '6px', border: isNearPayjump ? '1px solid rgba(16,185,129,0.2)' : '1px solid transparent', color: 'var(--accent-emerald)' } }>
          { isNearPayjump && "LADDERING ATIVO" }
        </div>
      </div>

      {/* CONTROLES QUANTUM */ }
      <div style={ { display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1.25rem', background: 'rgba(255,255,255,0.03)', padding: '1.5rem', borderRadius: '16px' } }>
        <div>
          <label htmlFor="perspective-opponents" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900 } }>Oponentes ({ numPlayers })</label>
          <input id="perspective-opponents" type="range" min="2" max="5" step="1" value={ numPlayers } onChange={ ( e ) => setNumPlayers( Number.parseInt( e.target.value ) ) } style={ { width: '100%', accentColor: 'var(--accent-danger)' } } />
        </div>
        <div style={ { display: 'flex', flexDirection: 'column', gap: '0.5rem', justifyContent: 'center' } }>
          <label htmlFor="perspective-payjump" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900, display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer' } }>
            <input id="perspective-payjump" type="checkbox" checked={ isNearPayjump } onChange={ ( e ) => setIsNearPayjump( e.target.checked ) } style={ { width: '16px', height: '16px', accentColor: 'var(--accent-emerald)' } } /> Perto de Payjump
          </label>
          <label htmlFor="perspective-blinds" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900, display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer' } }>
            <input id="perspective-blinds" type="checkbox" checked={ blindsRising } onChange={ ( e ) => setBlindsRising( e.target.checked ) } style={ { width: '16px', height: '16px', accentColor: 'var(--accent-danger)' } } /> Blinds Subindo
          </label>
        </div>
        <div>
          <label htmlFor="perspective-pko" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900 } }>PKO Bounty ({ Math.round( bountyValue * 100 ) }%)</label>
          <input id="perspective-pko" type="range" min="0" max="0.1" step="0.005" value={ bountyValue } onChange={ ( e ) => setBountyValue( Number.parseFloat( e.target.value ) ) } style={ { width: '100%', accentColor: 'var(--accent-gold)' } } />
        </div>

        <div>
          <label htmlFor="perspective-kappa" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900 } }>Credibilidade κ ({ Math.round( kappa * 100 ) }%)</label>
          <input id="perspective-kappa" type="range" min="0" max="1" step="0.05" value={ kappa } onChange={ ( e ) => setKappa( Number.parseFloat( e.target.value ) ) } style={ { width: '100%', accentColor: 'var(--accent-pink)' } } />
        </div>

        <div style={ { gridColumn: 'span 3', height: '1px', background: 'rgba(255,255,255,0.05)', margin: '0.5rem 0' } } />

        <div>
          <label htmlFor="perspective-equity" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900 } }>Equity ({ Math.round( winProb * 100 ) }%)</label>
          <input id="perspective-equity" type="range" min="0" max="1" step="0.01" value={ winProb } onChange={ ( e ) => setWinProb( Number.parseFloat( e.target.value ) ) } style={ { width: '100%', accentColor: 'var(--accent-indigo)' } } />
        </div>
        <div>
          <span style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900, display: 'block' } }>Sunk Cost / Pot</span>
          <div style={ { fontSize: '0.9rem', fontWeight: 900, color: 'var(--accent-amber)', fontFamily: 'monospace', marginTop: '0.35rem' } }>-{ heroCost.toFixed( 2 ) }bb / { potSize.toFixed( 1 ) }bb</div>
        </div>
        <div>
          <label htmlFor="perspective-realization" style={ { fontSize: '0.65rem', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 900 } }>Realização R ({ realization }x)</label>
          <input id="perspective-realization" type="range" min="0.5" max="1.5" step="0.05" value={ realization } onChange={ ( e ) => setRealization( Number.parseFloat( e.target.value ) ) } style={ { width: '100%', accentColor: 'var(--accent-emerald)' } } />
        </div>
      </div>

      {/* PIPELINE DE TRANSMUTAÇÃO QUANTUM */ }
      <div style={ { display: 'flex', flexDirection: 'column', gap: '0.8rem' } }>
        <MetricTooltip title="LAYER 1: ICMev (Snapshot)" desc="A fotografia estática. Fichas convertidas em equidade de prêmio (Malmuth-Harville). Ignora completamente a variância, a posição e o tempo. Útil como base, perigoso como conclusão.">
          <div className="hover:bg-slate-800/60 transition-colors" style={ { ...LAYER_STEP, borderLeftColor: 'var(--text-darker)' } }>
            <span style={ { fontSize: '0.7rem', fontWeight: 900, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' } }>LAYER 1: ICMev</span>
            <span style={ { fontSize: '1rem', fontWeight: 900, color: 'var(--text-light)' } }>{ result.currentEquityPct.toFixed( 2 ) }%</span>
          </div>
        </MetricTooltip>

        <MetricTooltip title="LAYER 2: Esperança Matemática" desc="A injeção da Lógica. O Valuation corrige a assimetria (fichas ganhas vs perdidas) e a Dívida RIO pune a insolvência de múltiplos jogadores no pote.">
          <div className="hover:bg-slate-800/60 transition-colors" style={ { ...LAYER_STEP, borderLeftColor: 'var(--accent-amber)' } }>
            <div>
              <span style={ { fontSize: '0.7rem', fontWeight: 900, color: 'var(--accent-amber)', display: 'block', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.2rem' } }>LAYER 2: ESPERANÇA MATEMÁTICA (LÓGICA)</span>
              <span style={ { fontSize: '0.65rem', color: 'var(--text-dim)', fontWeight: 600 } }>Valuation: <strong className="text-amber-500/80">{ result.valuation.toFixed( 2 ) }x</strong> | Dívida RIO: <strong className="text-amber-500/80">-{ result.rioLiability.toFixed( 2 ) }%</strong></span>
            </div>
            <span style={ { fontSize: '1rem', fontWeight: 900, color: 'var(--accent-amber)' } }>Explosão: { ( ( result.valuation - 1 ) * 100 ).toFixed( 0 ) }%</span>
          </div>
        </MetricTooltip>

        <MetricTooltip title="LAYER 3: Expectativa Preditiva" desc="A Psicologia do Tempo. FGS mede a urgência da sobrevivência (t-3 blinds) e o Piso Dinâmico estabelece o verdadeiro custo do fold.">
          <div className="hover:bg-slate-800/60 transition-colors" style={ { ...LAYER_STEP, borderLeftColor: 'var(--accent-emerald)' } }>
            <div>
              <span style={ { fontSize: '0.7rem', fontWeight: 900, color: 'var(--accent-emerald)', display: 'block', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.2rem' } }>LAYER 3: EXPECTATIVA MATEMÁTICA (PREDITIVA)</span>
              <span style={ { fontSize: '0.65rem', color: 'var(--text-dim)', fontWeight: 600 } }>Piso (EV_fold): <strong className="text-emerald-500/80">{ result.dynamicEvFold.toFixed( 2 ) }%</strong> | FGS Health: <strong className="text-emerald-500/80">{ result.fgsHealth.toFixed( 2 ) }x</strong></span>
            </div>
            <span style={ { fontSize: '1rem', fontWeight: 900, color: 'var(--accent-emerald)' } }>{ result.isActionBetterThanFold ? "Soberano" : "Insolvente" }</span>
          </div>
        </MetricTooltip>

        <MetricTooltip title="LAYER 4: Perspectiva Matemática" desc="A Síntese Máxima SOTA. Se o valor é positivo, a utilidade da colisão supera o piso estrutural do fold e a erosão do tempo, justificando a agressão.">
          <div style={ { borderLeft: '4px solid var(--accent-indigo-light)', background: 'rgba(99,102,241,0.1)', border: '1px solid rgba(99,102,241,0.3)', padding: '1.5rem', borderRadius: '12px', boxShadow: '0 8px 30px rgba(99,102,241,0.15)' } }>
            <div style={ { display: 'flex', justifyContent: 'space-between', alignItems: 'center' } }>
              <div>
                <span style={ { fontSize: '0.8rem', fontWeight: 900, color: 'var(--accent-indigo-light)', display: 'block', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.3rem' } }>LAYER 4: PERSPECTIVA MATEMÁTICA (PM)</span>
                <span style={ { fontSize: '0.65rem', color: 'var(--text-light)', fontWeight: 600 } }>Edge Amortizada: <strong className="text-indigo-300">{ result.amortizedEdge.toFixed( 2 ) }x</strong> | Cᵢ: <strong className="text-indigo-300">{ result.ci.toFixed( 2 ) }</strong> | κ: <strong className="text-indigo-300">{ Math.round( kappa * 100 ) }%</strong></span>
              </div>
              <span style={ { fontSize: '2rem', fontWeight: 900, color: result.isActionBetterThanFold ? 'var(--accent-emerald)' : 'var(--accent-danger)' } }>
                { result.perspectivaPct.toFixed( 2 ) }%
              </span>
            </div>
            { Math.abs( result.perspectivaPct ) <= 5 && (
              <div style={ { marginTop: '1rem', padding: '0.85rem', background: 'rgba(244, 63, 94, 0.1)', border: '1px solid rgba(244, 63, 94, 0.3)', borderRadius: '8px', fontSize: '0.65rem', color: 'var(--accent-pink-light)', fontWeight: 800, lineHeight: 1.5 } }>
                <i className="fa-solid fa-triangle-exclamation mr-2"></i> ZONA MARGINAL (EV INSTÁVEL): Decisão altamente sensível à imprecisão de range.
                <div style={ { marginTop: '0.4rem', color: 'var(--text-bright)', fontStyle: 'italic', fontWeight: 600 } }>&quot;O tamanho do desvio (exploit) deve ser proporcional à credibilidade da sua informação.&quot; — Axioma Lipe Piv</div>
              </div>
            ) }
          </div>
        </MetricTooltip>
      </div>

      {/* EQUITY CURVES CHART */ }
      <div style={ { height: '180px', background: 'rgba(15,23,42,0.4)', borderRadius: '16px', padding: '1.25rem 0.5rem 0.5rem 0', border: '1px solid rgba(255,255,255,0.05)' } }>
        { chartElement }
      </div>

      {/* DIAGNÓSTICO SOTA */ }
      <div style={ { padding: '1.25rem', background: 'rgba(99,102,241,0.08)', borderLeft: '4px solid var(--accent-indigo)', borderRadius: '8px', fontSize: '0.75rem', color: 'var(--text-light)', lineHeight: 1.6 } }>
        <strong className="text-indigo-400">SÍNTESE QUANTUM:</strong> { result.diagnostico }
        <div style={ { marginTop: '0.4rem' } }>
          <span style={ { color: 'var(--text-muted)' } }>Protocolo: { result.isActionBetterThanFold ? "A utilidade da colisão neutraliza a erosão do tempo." : "A omissão estratégica preserva o capital sistêmico." }</span>
        </div>
        { isNearPayjump && <div style={ { marginTop: '0.8rem', padding: '0.75rem', background: 'rgba(245,158,11,0.1)', borderRadius: '6px', border: '1px solid rgba(245,158,11,0.2)', color: 'var(--accent-gold)', fontWeight: 700 } }><i className="fa-solid fa-bolt mr-2"></i>[EXTREMA AVERSÃO AO RISCO]: A pressão de payjump induz o overfold. A inversão de EVs negativos da teoria pura exige um desvio (exploit) estritamente proporcional à credibilidade dessa leitura (Axioma Lipe Piv).</div> }
      </div>
    </div>
  );
}

'use client';

/**
 * IDENTITY: Painel de Teoria com Tabs (SOTA v4.1)
 * PATH: src/components/simulator/panels/TheoryPanel.tsx
 * ROLE: Exibir Fundamento Teórico, Diluição SPR, Vetor de Exploit e Quiz por cenário.
 *       Visão Arquitetural SOTA com alta densidade de informação e RP Dinâmico.
 * BINDING: [engine/types.ts, ui/SprPipeline.tsx, ui/QuizEngine.tsx, simulator.module.css]
 */

import { MetricTooltip } from '@/app/ICMlaboratory/RiskPremiumDashboard';
import { QuizEngine } from '@/components/quiz/QuizEngine';
import type { QuizQuestion as NormalizedQuestion } from '@/components/quiz/types';
import { useContext, useEffect, useMemo, useState } from 'react';
import { NashConvergenceMatrix } from '../../TheoryPanel/NashConvergenceMatrix';
import DegradationChart from '../charts/DegradationChart';
import type { Scenario, ScenarioQuiz, SprStage } from '../engine/types';
import { SotaMetricsContext, SotaSpotContext, SotaWasmContext } from '../SotaContext';
import SprPipeline from '../ui/SprPipeline';

interface TheoryPanelProps {
  scenario: Scenario;
  /** sprData recalculado com RP derivado (M-H). Fallback: scenario.sprData */
  effectiveSprData?: SprStage[];
  /** Risk Premium dinâmico (IP) calculado pelo motor Quantum */
  effectiveIpRp?: number;
  /** Risk Premium dinâmico (OOP) calculado pelo motor Quantum */
  effectiveOopRp?: number;
}

type TabId = 'theory' | 'ranges' | 'bubble' | 'spr' | 'exploit' | 'quiz';

const TABS: { id: TabId; label: string; icon: string }[] = [
  { id: 'theory', label: 'Fundamento', icon: 'fa-book-journal-whills' },
  { id: 'ranges', label: 'Ranges SOTA', icon: 'fa-border-all' },
  { id: 'bubble', label: 'Pressão / RP', icon: 'fa-gauge-high' },
  { id: 'spr', label: 'Diluição (SPR)', icon: 'fa-water' },
  { id: 'exploit', label: 'Vetor Exploit', icon: 'fa-crosshairs' },
  { id: 'quiz', label: 'Validação', icon: 'fa-microscope' },
];

const calcBF = ( rp: number ) => {
  if ( rp >= 100 ) return 999; // Evitar infinito que quebra UI
  return 100 / ( 100 - rp );
};

function BubbleFactorDiagnostic ( { ipRp, oopRp }: Readonly<{ ipRp: number; oopRp: number }> ) {
  const ipBf = calcBF( ipRp );
  const oopBf = calcBF( oopRp );
  const deltaRp = ipRp - oopRp;
  const ipEquity = ipBf / ( ipBf + 2 );
  const oopEquity = oopBf / ( oopBf + 2 );
  const chipEvEquity = 1 / 3;
  const ipDelta = ( ( ipEquity - chipEvEquity ) * 100 ).toFixed( 1 );
  const oopDelta = ( ( oopEquity - chipEvEquity ) * 100 ).toFixed( 1 );

  const hasIpAdvantage = deltaRp < 0;

  let deltaLabel = 'Simetria de Pressão (ΔRP 0%)';
  let panelBgClass = 'bg-slate-800/30 border-white/5';
  let iconBgClass = 'bg-slate-700 text-slate-400';
  let iconClass = 'fa-equals';
  let textClass = 'text-slate-300';

  if ( hasIpAdvantage )
  {
    deltaLabel = `IP com Vantagem de Risco (ΔRP ${Math.abs( deltaRp ).toFixed( 1 )}%)`;
    panelBgClass = 'bg-emerald-950/20 border-emerald-500/20';
    iconBgClass = 'bg-emerald-500/10 text-emerald-400';
    iconClass = 'fa-bolt';
    textClass = 'text-emerald-400';
  } else if ( deltaRp > 0 )
  {
    deltaLabel = `IP sob Punição de Valuation (ΔRP +${deltaRp.toFixed( 1 )}%)`;
    panelBgClass = 'bg-rose-950/20 border-rose-500/20';
    iconBgClass = 'bg-rose-500/10 text-rose-400';
    iconClass = 'fa-weight-hanging';
    textClass = 'text-rose-400';
  }

  return (
    <div className="space-y-6">
      <div className="p-4 rounded-xl bg-slate-900/50 border border-white/5">
        <h4 className="text-[0.65rem] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
          <i className="fa-solid fa-scale-unbalanced text-fuchsia-500" /> Diagnóstico de Assimetria (Malmuth-Harville)
        </h4>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <MetricTooltip align="left" title="Agressor (IP)" desc="O agressor dita o preço. Se o RP dele é significativamente menor, ele usa o Leverage para extrair Fold Equity não-linear da mesa.">
            <div className="h-full p-4 rounded-lg bg-indigo-950/20 border border-indigo-500/20 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-2 opacity-10"><i className="fa-solid fa-khanda text-4xl text-indigo-400" /></div>
              <p className="text-[0.6rem] text-indigo-400 font-bold uppercase tracking-widest mb-1">Agressor (IP)</p>
              <div className="flex items-baseline gap-2 mb-2">
                <span className="text-3xl font-black text-indigo-300 font-mono leading-none">{ ipRp.toFixed( 1 ) }%</span>
                <span className="text-xs text-indigo-500 font-mono">RP</span>
              </div>
              <p className="text-xs text-slate-400 m-0">BF Equivalente: <span className="text-indigo-300 font-mono font-bold">{ ipBf.toFixed( 2 ) }x</span></p>
              <div className="mt-4 pt-3 border-t border-indigo-500/10">
                <p className="text-[0.65rem] text-slate-400 mb-1">Custo de Defesa (Pot-Size):</p>
                <p className="text-sm font-bold text-indigo-300">{ ( ipEquity * 100 ).toFixed( 1 ) }% <span className="text-xs font-normal text-slate-500">vs 33.3% ChipEV</span></p>
                <p className="text-[0.6rem] text-rose-400 font-bold">+{ ipDelta }pp de inflação sobre MDF</p>
              </div>
            </div>
          </MetricTooltip>

          <MetricTooltip align="right" title="Defensor (OOP)" desc="O defensor paga a conta do ICM. Ele precisa de uma mão exponencialmente mais forte para justificar o call, ancorando a defesa no Teto de Risco.">
            <div className="h-full p-4 rounded-lg bg-rose-950/20 border border-rose-500/20 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-2 opacity-10"><i className="fa-solid fa-shield-halved text-4xl text-rose-400" /></div>
              <p className="text-[0.6rem] text-rose-400 font-bold uppercase tracking-widest mb-1">Defensor (OOP)</p>
              <div className="flex items-baseline gap-2 mb-2">
                <span className="text-3xl font-black text-rose-300 font-mono leading-none">{ oopRp.toFixed( 1 ) }%</span>
                <span className="text-xs text-rose-500 font-mono">RP</span>
              </div>
              <p className="text-xs text-slate-400 m-0">BF Equivalente: <span className="text-rose-300 font-mono font-bold">{ oopBf.toFixed( 2 ) }x</span></p>
              <div className="mt-4 pt-3 border-t border-rose-500/10">
                <p className="text-[0.65rem] text-slate-400 mb-1">Custo de Defesa (Pot-Size):</p>
                <p className="text-sm font-bold text-rose-300">{ ( oopEquity * 100 ).toFixed( 1 ) }% <span className="text-xs font-normal text-slate-500">vs 33.3% ChipEV</span></p>
                <p className="text-[0.6rem] text-rose-400 font-bold">+{ oopDelta }pp de inflação sobre MDF</p>
              </div>
            </div>
          </MetricTooltip>
        </div>
      </div>

      <div className={ `p-4 rounded-xl border flex items-center gap-4 ${panelBgClass}` }>
        <div className={ `w-12 h-12 rounded-full flex items-center justify-center shrink-0 ${iconBgClass}` }>
          <i className={ `fa-solid ${iconClass} text-lg` } />
        </div>
        <div>
          <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-widest mb-1">Vetor de Distorção de Nash</p>
          <p className={ `text-lg font-black m-0 font-mono ${textClass}` }>
            { deltaRp > 0 ? '+' : '' }{ deltaRp.toFixed( 1 ) }% ΔRP
          </p>
          <p className="text-xs text-slate-400 m-0 mt-0.5">{ deltaLabel }</p>
        </div>
      </div>
    </div>
  );
}

// SOTA (Otimização de Complexidade Ciclomática - SonarLint S3776)
// Adaptador puro e desacoplado: transpila formato de quiz para NormalizedQuestion[]
const normalizeQuizData = ( quizData: ScenarioQuiz | null | undefined, scenarioId: string ): NormalizedQuestion[] => {
  if ( !quizData ) return [];
  const rawList: ScenarioQuiz[] = Array.isArray( quizData ) ? quizData : [ quizData ];

  return rawList
    .map( ( q, index ): NormalizedQuestion | null => {
      if ( !q ) return null;
      const questionText = q.question || 'Pergunta nao definida';
      const rawOptions = q.options || [];
      const correctIdx = rawOptions.findIndex( opt => opt.isCorrect );
      const correctId = rawOptions[ correctIdx ]?.id || `opt-${Math.max( 0, correctIdx )}`;

      return {
        id: `q-${scenarioId}-${index}`,
        text: questionText,
        options: rawOptions.map( ( opt, i ) => ( {
          id: opt.id || `opt-${i}`,
          label: opt.text || 'Opcao vazia',
        } ) ),
        correctOptionId: correctId,
        explanation: q.explanation || '',
      };
    } )
    .filter( ( q ): q is NormalizedQuestion => q !== null );
};

// SOTA: Heurística de ChipEV (Vácuo / GTO) isolada para fricção zero cognitiva
function calculatePureEv ( rankValue: number, isSuited: boolean, isPair: boolean ): number {
  if ( rankValue >= 16 ) return ( rankValue - 15 ) * 0.8;
  if ( rankValue >= 13 && ( isSuited || isPair ) ) return ( rankValue - 12 ) * 0.3;
  if ( rankValue >= 10 && isSuited ) return 0.1;
  return -0.5;
}

// SOTA: Passivo Sistêmico isolado para previsibilidade matemática
function calculateInsolvencyDelta ( rankValue: number, isSuited: boolean, isPair: boolean, rpFactor: number, pureEv: number ): number {
  if ( rpFactor <= 0 || pureEv <= -1 ) return 0;

  let rioVulnerability = 1.2;
  if ( isSuited ) rioVulnerability = 0.5;
  else if ( isPair ) rioVulnerability = 0.3;

  return -( rpFactor * 0.05 ) * rioVulnerability * Math.max( 0.5, ( 22 - rankValue ) * 0.15 );
}

// SOTA: Avaliação vetorial de uma célula
function calculateFallbackCell ( i: number, j: number, rpFactor: number, ranks: string[] ) {
  const isPair = i === j;
  const isSuited = j > i;

  let combo = `${ranks[ j ]}${ranks[ i ]}o`;
  if ( isPair ) combo = `${ranks[ i ]}${ranks[ j ]}`;
  else if ( isSuited ) combo = `${ranks[ i ]}${ranks[ j ]}s`;

  const rankValue = ( 14 - i ) + ( 14 - j );
  const pureEv = calculatePureEv( rankValue, isSuited, isPair );
  const insolvencyDelta = calculateInsolvencyDelta( rankValue, isSuited, isPair, rpFactor, pureEv );

  return { combo, pureEv, insolvencyDelta, isSuited, isPair };
}

// SOTA: Função Pura extraída para erradicar a Complexidade Ciclomática (SonarLint S3776)
function generateFallbackMatrix ( ipRp: number, oopRp: number ) {
  const ranks = [ 'A', 'K', 'Q', 'J', 'T', '9', '8', '7', '6', '5', '4', '3', '2' ];
  const fallback = [];
  const rpFactor = Math.max( ipRp, oopRp );

  for ( let i = 0; i < ranks.length; i++ )
  {
    for ( let j = 0; j < ranks.length; j++ )
    {
      fallback.push( calculateFallbackCell( i, j, rpFactor, ranks ) );
    }
  }
  return fallback;
}

export default function TheoryPanel ( { scenario, effectiveSprData, effectiveIpRp, effectiveOopRp }: Readonly<TheoryPanelProps> ) {
  const [ activeTab, setActiveTab ] = useState<TabId>( 'theory' );
  const [ isDynamicRpActive, setIsDynamicRpActive ] = useState( true );

  // SOTA: Bebe diretamente do Sangue Matemático (Contexto SOTA), descartando props defasadas
  const spotContext = useContext( SotaSpotContext );
  const metricsContext = useContext( SotaMetricsContext );
  const wasmContext = useContext( SotaWasmContext );

  // Prioriza o RP dinâmico (Quantum) calculado pelo MasterSimulator
  const ipRp = spotContext?.effectiveIpRp ?? effectiveIpRp ?? scenario.ipRp;
  const oopRp = spotContext?.effectiveOopRp ?? effectiveOopRp ?? scenario.oopRp;

  const effStack = Math.min( scenario.stacks[ 0 ] || 40, scenario.stacks[ 1 ] || 40 );
  const preflopPot = ( effectiveSprData ?? scenario.sprData )[ 0 ]?.potSize || 2.5;

  // Reset tab ao mudar cenário
  useEffect( () => {
    setActiveTab( 'theory' );
  }, [ scenario.id ] );

  // SOTA: Erradicação do mock. Orquestração com o motor Rust (WASM).
  useEffect( () => {
    if ( activeTab === 'ranges' && wasmContext?.dispatchInsolvencyMatrix )
    {
      const heroInvested = spotContext?.heroInvested ?? 1;
      const currentPot = spotContext?.spotData?.pot ?? 2.5;
      const activePlayers = spotContext?.activePlayers ?? 2;
      // Submissão do fator RP de maior gravidade posicional para testar a matriz.
      const rpFactor = Math.max( ipRp, oopRp );
      const villainRange = "100%";
      const board = "";

      wasmContext.dispatchInsolvencyMatrix( villainRange, board, rpFactor, heroInvested, currentPot, activePlayers );
    }
  }, [ activeTab, scenario.id, ipRp, oopRp, spotContext?.heroInvested, spotContext?.spotData?.pot, spotContext?.activePlayers, wasmContext?.dispatchInsolvencyMatrix ] );

  // SOTA: Fallback Heurístico (Auto-Healing)
  // Garante a densidade visual e didática caso o Motor WASM falhe ou atrase,
  // simulando a pressão matemática (Insolvência) com base no RP ativo.
  const matrixDataToRender = useMemo( () => {
    if ( wasmContext?.insolvencyMatrixData && wasmContext.insolvencyMatrixData.length > 0 ) return wasmContext.insolvencyMatrixData;
    return generateFallbackMatrix( ipRp, oopRp );
  }, [ wasmContext?.insolvencyMatrixData, ipRp, oopRp ] );

  return (
    <div className="glass-panel border border-white/5 rounded-2xl shadow-2xl shadow-slate-900/50 bg-(--bg-deep)/80 backdrop-blur-md flex flex-col transition-all duration-500">

      {/* Header do Painel */ }
      <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 bg-linear-to-r from-slate-900/80 to-transparent">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-fuchsia-500/10 border border-fuchsia-500/20 flex items-center justify-center text-fuchsia-400">
            <i className="fa-solid fa-atom text-sm"></i>
          </div>
          <div>
            <h3 className="text-sm font-bold text-slate-200 m-0 uppercase tracking-wider">Câmara Analítica</h3>
            <p className="text-[0.65rem] text-slate-500 m-0 font-mono tracking-widest mt-0.5">ESTADO DA ARTE V4.1</p>
          </div>
        </div>
      </div>

      {/* Tabs */ }
      <div className="flex flex-wrap border-b border-white/5 bg-slate-950/50 px-2 pt-2 gap-1 justify-center sm:justify-start">
        { TABS.map( ( tab ) => (
          <button
            key={ tab.id }
            onClick={ () => setActiveTab( tab.id ) }
            className={ `
              flex items-center gap-2 px-4 py-3 text-[0.65rem] font-bold uppercase tracking-widest transition-all
              border-b-2 whitespace-nowrap rounded-t-lg
              ${activeTab === tab.id
                ? 'text-fuchsia-400 border-fuchsia-500 bg-linear-to-t from-fuchsia-500/10 to-transparent'
                : 'text-slate-500 border-transparent hover:text-slate-300 hover:bg-white/5'}
            `}
          >
            <i className={ `fa-solid ${tab.icon} ${activeTab === tab.id ? 'opacity-100 scale-110' : 'opacity-50'} transition-transform` } />
            { tab.label }
          </button>
        ) ) }
      </div>

      {/* Conteúdo por tab */ }
      <div className="flex-1 p-6 flex flex-col min-h-87.5 transition-all duration-500">
        <div className="animate-fade-in w-full" key={ `${scenario.id}-${activeTab}` }>

          {/* TAB: FUNDAMENTO */ }
          { activeTab === 'theory' && (
            <div className="prose prose-invert prose-fuchsia prose-sm max-w-none text-slate-300">
              <div className="mb-6 p-4 rounded-lg bg-indigo-950/30 border border-indigo-500/20 flex gap-4 items-start">
                <i className="fa-solid fa-circle-info text-indigo-400 mt-1"></i>
                <p className="m-0 text-xs leading-relaxed text-indigo-200/80">
                  <strong className="text-indigo-300">Nota SOTA v4.1:</strong> A Perspectiva Matemática agora integra a <span className="text-emerald-300 font-bold">Amortização da Edge</span> (Poda da Árvore) e a <span className="text-rose-400 font-bold">Insolvência Multiway (Cᵢ)</span>. O <code className="text-fuchsia-300 bg-fuchsia-900/30 px-1 rounded">EV_fold</code> atua como baseline dinâmico punido por RIO exponencial em potes MW. As justificativas abaixo englobam o risco de <em>Pot Entrapment</em> e a diluição do RP.
                </p>
              </div>
              <div dangerouslySetInnerHTML={ { __html: scenario.theory } } />
            </div>
          ) }

          {/* TAB: RANGES */ }
          { activeTab === 'ranges' && (
            <div className="h-full space-y-4">
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 sm:gap-3 mb-4 p-3 sm:p-4 rounded-xl bg-slate-900/50 border border-white/5 shadow-inner">
                <div className="flex items-center gap-3">
                  <i className="fa-solid fa-filter text-fuchsia-400"></i>
                  <span id="rp-toggle-label" className="text-xs font-bold text-fuchsia-400 uppercase tracking-wider cursor-pointer">
                    Filtro de Perspectiva (RP Dinâmico)
                  </span>
                </div>
                <button
                  type="button"
                  role="switch"
                  aria-checked={ isDynamicRpActive }
                  aria-labelledby="rp-toggle-label"
                  onClick={ () => setIsDynamicRpActive( !isDynamicRpActive ) }
                  className={ `${isDynamicRpActive ? 'bg-fuchsia-600' : 'bg-zinc-700'
                    } relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-fuchsia-500 focus:ring-offset-2 focus:ring-offset-slate-900` }
                >
                  <span
                    aria-hidden="true"
                    className={ `${isDynamicRpActive ? 'translate-x-5' : 'translate-x-0'
                      } pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out` }
                  />
                </button>
              </div>
              { wasmContext?.isCalculatingInsolvency ? (
                <div className="flex items-center justify-center p-12 text-fuchsia-400">
                  <i className="fa-solid fa-circle-notch fa-spin text-3xl mr-4"></i>
                  <span className="font-mono text-sm tracking-widest uppercase">Forjando Matriz de Insolvência SOTA...</span>
