/**
 * IDENTITY: Motor de Métricas Quânticas (SOTA)
 * PATH: src/components/simulator/engine/quantumMetrics.ts
 * ROLE: Centralizar os cálculos de Perspectiva Matemática, Valuation, RIO e FGS.
 * BINDING: [src/components/simulator/MasterSimulator.tsx]
 */

import type { PerspectivaResult } from '@/lib/perspectiva';
import { calculateRioTension } from '@/lib/perspectiva';
import type { HeroPosition } from '../MasterSimulator';

/**
 * Calcula métricas profundas baseadas na Perspectiva Matemática.
 */
export function computeQuantumMetrics(
    quantumPerspectiva: PerspectivaResult,
    activePlayers: number,
    heroInvested: number,
    currentPot: number,
    stacks: number[],
    heroRawStack: number,
    totalTableChips: number,
    handEquity: number = 50,
    kappa: number = 0.5
) {
    // SOTA: Axioma Lipe Piv (Regressão Bayesiana)
    // Cura da Esquizofrenia: A Equidade base é puramente ditada pelas Pot Odds. O Fator Ψ regula a fé na matemática ideal.
    const winProb = handEquity / 100;
    const baselineEquity = ( currentPot + heroInvested ) > 0 ? heroInvested / ( currentPot + heroInvested ) : 0;
    const bayesianWinProb = baselineEquity + kappa * ( winProb - baselineEquity );

    const deltaWinPct = quantumPerspectiva.deltaWinPct ?? 0;
    const deltaLosePct = quantumPerspectiva.deltaLosePct ?? 0;
    const evFoldPct = quantumPerspectiva.dynamicEvFold ?? 0;
    const rFactor = 1; // SOTA: A realização (R) já foi sintetizada no núcleo do Motor
    const fgsHealth = quantumPerspectiva.fgsHealth ?? 1;

    // SOTA: Amortização de Edge baseada em log(S)
    // A árvore de decisão colapsa em stacks curtos, neutralizando a Edge e aumentando a variância.
    const sEff = Math.max( 2, Math.min( stacks[0] ?? 40, stacks[1] ?? 40 ) );
    const varianceSigma = 0.8; // Variância base de colisão
    const deltaHabilidade = 1.2; // Superioridade técnica do Hero
    // Er(S) = (Sigma / DeltaHabilidade) * log10(S) -> Escalado para fator multiplicador
    let amortizedEdgeMultiplier = ( varianceSigma / deltaHabilidade ) * Math.log10( sEff ) * 1.5;
    amortizedEdgeMultiplier = Math.max( 0.2, Math.min( 2.5, amortizedEdgeMultiplier ) ); // Limites de amortização

    const adjustedDeltaWin = deltaWinPct * amortizedEdgeMultiplier;

    const opponents = Math.max( 1, activePlayers - 1 );
    // SOTA: Escalonamento Quadrático (x^2) para Multiway (Morte do Anti-Smoothing)
    const mwFactor = Math.pow( opponents, 2 );
    const baseRioPct = 0.15;
    const baseRio = heroInvested * baseRioPct;
    let rioMw = baseRio * mwFactor;

    // SOTA: Vetor de Manutenção de Monopólio
    const monopolyFactor = totalTableChips > 0 ? ( heroRawStack / totalTableChips ) : 0;
    let monopolyMaintenanceTax = 0;
    if ( monopolyFactor >= 0.35 ) {
        // Decaimento abrupto (80%) do RIO para o monopolista (Imunidade à catástrofe silenciosa)
        rioMw *= 0.2;
        // Taxa de Manutenção de Monopólio: O custo sistêmico de foldar e permitir que um stack médio devore um short stack
        monopolyMaintenanceTax = ( totalTableChips * 0.05 ) * ( evFoldPct > 0 ? 1 : -1 );
    }

    // SOTA: O Fold não sofre RIO. O RIO é o passivo estrutural de continuar na mão.
    const adjustedEvFold = evFoldPct + monopolyMaintenanceTax;

    const esperanca = ( bayesianWinProb * adjustedDeltaWin ) + ( ( 1 - bayesianWinProb ) * deltaLosePct );
    const expectativa = ( bayesianWinProb * adjustedDeltaWin * rFactor * fgsHealth ) + ( ( 1 - bayesianWinProb ) * deltaLosePct );

    // SOTA: Instabilidade de EVs (Mutação da Margem)
    // Evidencia a fragilidade do EV marginal, adicionando incerteza baseada no SPR e agressão
    const marginInstability = Math.max( 0.01, 1 / sEff ) * 100; // Incerteza %

    // SOTA: Equação de Perspectiva Matemática (Diferencial de Abismo)
    // PM = (Expectativa - RIO) - EV_Fold
    const perspectiva = expectativa - rioMw - adjustedEvFold;

    const denom = ( adjustedDeltaWin * rFactor * fgsHealth ) - deltaLosePct;
    let threshEq = null;
    // SOTA: A Equidade Limite (Teto) DEVE subir para compensar o passivo do RIO.
    if ( Math.abs( denom ) > 1e-6 ) threshEq = Math.max( 0, Math.min( 1, ( adjustedEvFold + rioMw - deltaLosePct ) / denom ) );

    let ci = null;
    const potOdds = ( currentPot + heroInvested ) > 0 ? heroInvested / ( currentPot + heroInvested ) : 0;
    if ( threshEq !== null && threshEq > 0 ) ci = potOdds / threshEq;

    return {
        amortizedEdgeMultiplier, rioMw, adjustedEvFold, esperanca, expectativa, perspectiva, threshEq, ci, marginInstability,
        isSolvent: ci !== null && ci >= 1,
        isActionable: perspectiva > 0
    };
}

/**
 * Gera as métricas para as ações (Fold, Call, Raise) no painel.
 */
export function calculateActionMetrics( params: {
    heroInvested: number;
    currentPot: number;
    bfForDash: number;
    rpForDash: number;
    quantumPerspectiva: PerspectivaResult | null;
    heroRawStack: number;
    heroPosition: HeroPosition;
    baseFgsErosion: number;
    apiQuantumMetrics?: {
        adjustedEvFold: number;
        perspectiva: number;
        ci: number | null;
    } | null;
    activePlayers: number;
    totalTableChips: number;
} ) {
    const { heroInvested, currentPot, bfForDash, rpForDash, quantumPerspectiva, heroRawStack, heroPosition, baseFgsErosion, apiQuantumMetrics, activePlayers, totalTableChips } = params;
    const fallbackFold = quantumPerspectiva ? ( quantumPerspectiva.dynamicEvFold ?? 0 ) : -heroInvested * ( 1 + ( rpForDash / 200 ) );
    const foldPerspectiva = apiQuantumMetrics?.adjustedEvFold ?? fallbackFold;
    const fallbackCall = quantumPerspectiva ? ( quantumPerspectiva.perspectivaPct ?? 0 ) : ( currentPot * 0.3 );
    const callPerspectiva = apiQuantumMetrics?.perspectiva ?? fallbackCall;
    const callChipEv = quantumPerspectiva ? ( ( quantumPerspectiva.deltaWinPct ?? 0 ) * 0.5 + ( quantumPerspectiva.deltaLosePct ?? 0 ) * 0.5 ) : currentPot * 0.3;
    const opponents = Math.max( 1, activePlayers - 1 );
    const multiwayMultiplier = Math.pow( opponents, 2 );
    let baseRioLiability = ( quantumPerspectiva ? ( quantumPerspectiva.rioLiability ?? 0 ) : rpForDash ) * multiwayMultiplier;

    // SOTA: Vetor de Manutenção de Monopólio amortece a tensão global
    const isMonopolist = totalTableChips > 0 && ( heroRawStack / totalTableChips ) >= 0.35;
    if ( isMonopolist ) {
        baseRioLiability *= 0.2;
    }

    const posType = heroPosition === 'IP' ? 'IP' : 'OOP';
    let rioTension = 1;
    if ( apiQuantumMetrics?.ci == null || apiQuantumMetrics.ci >= 1 ) rioTension = calculateRioTension( heroInvested, currentPot, heroRawStack, posType, baseRioLiability );
    const raiseTension = calculateRioTension( heroInvested, currentPot, heroRawStack, posType, rpForDash, 0.6 );

    return {
        fold: { chipEv: -heroInvested, perspectiva: foldPerspectiva, fgsImpact: baseFgsErosion, tension: 0 },
        call: { chipEv: callChipEv, perspectiva: callPerspectiva, fgsImpact: baseFgsErosion * 0.5, tension: rioTension },
        raise: { chipEv: currentPot * 0.8, perspectiva: callPerspectiva * bfForDash, fgsImpact: Math.abs( baseFgsErosion ), tension: raiseTension }
    };
}

/**
 * Calcula a erosão base do FGS (Future Game Simulations).
 */
export function calculateBaseFgsErosion(
    quantumPerspectiva: PerspectivaResult | null,
    blindsRisingSoon: boolean,
    anteSize: number,
    heroPosition: HeroPosition,
    heroRawStack: number,
    totalTableChips: number
): number {
    if ( quantumPerspectiva ) return ( quantumPerspectiva.dynamicEvFold ?? 0 ) - ( quantumPerspectiva.deltaFoldPct ?? 0 );
    if ( blindsRisingSoon ) {
        const timeErosion = -( anteSize / 100 ) * 3;

        // SOTA: Vetor de Manutenção de Monopólio
        const isMonopolist = totalTableChips > 0 && ( heroRawStack / totalTableChips ) >= 0.35;
        if ( isMonopolist ) {
            // Inversão Gravitacional (FGS Positivo): O Monopolista lucra passivamente com a morte térmica dos adversários
            return Math.abs( timeErosion ) * 1.5;
        }

        // SOTA: Inversão Gravitacional de Órbita (FGS t-3)
        const penaltyMap: Record<HeroPosition, number> = { IP: -1.5, BB: -0.5, SB: 0 };
        return timeErosion + ( penaltyMap[heroPosition] ?? 0 );
    }
    return 0;
}

/**
 * IDENTITY: Motor de Distorcao ICM pos-flop
 * PATH: src/components/simulator/engine/nashSolver.ts
 * ROLE: Aplicar distorcao ICM sobre frequencias ChipEV via equacao concava.
 *       Sintetiza a distorcao baseado estritamente na Hierarquia da Perspectiva Matematica (PMev).
 *       Export principal: solveIcmDistortion. solveNash = alias deprecated para retrocompatibilidade.
 *
 * HIERARQUIA VITOI (PMev):
 *   1. ICMev (RP): O imposto estrutural bruto de sobrevivencia.
 *   2. Esperanca Matematica: O RP eleva o sarrafo de Pot Odds linearmente.
 *   3. Expectativa Matematica: Reverse Implied Odds (RIO) aplicam penalizacao quadratica (RP/10)^2 ao OOP.
 *   4. Perspectiva Matematica: A soma (Esperanca + Expectativa) oblitera o Call marginal. O Fold absorve o deficit.
 *
 */

import type { ChipEvFreqs, FreqResult, IcmDistortionResult } from './types';

/**
 * Formula o Spread de Incerteza dinamico baseado na tensao do spot.
 */
function calcSpread ( deltaRp: number ): number {
  return Math.max( 3, Math.abs( deltaRp ) * 0.25 );
}

/**
 * Aplica distorcao ICM sobre frequencias ChipEV para calcular frequencias pos-flop ajustadas.
 * Motor guiado estritamente pela Hierarquia SOTA (PMev).
 *
 * @param ipRp           - Risk Premium do IP (0–100), via Malmuth-Harville
 * @param oopRp          - Risk Premium do OOP (0–100), via Malmuth-Harville
 * @param chipEvFreqs    - Frequencias ChipEV do spot (GTO Wizard ou equivalente)
 * @param aggressionFactor - Desvio comportamental real do oponente vs equilibrio ICM
 *                           (0.5 = passivo · 1.0 = equilibrio)
 * @param activePlayers    - Quantidade de jogadores na mão. Multiplica RIO exponencialmente em pots MW.
 */
export function solveIcmDistortion (
  ipRp: number,
  oopRp: number,
  chipEvFreqs: ChipEvFreqs,
  aggressionFactor = 1,
  activePlayers = 2,
): IcmDistortionResult {
  const safeIp = Math.max( 0, Math.min( 100, Number( ipRp ) || 0 ) );
  const safeOop = Math.max( 0, Math.min( 100, Number( oopRp ) || 0 ) );
  const safeFactor = Math.max( 0.1, Math.min( 3, Number( aggressionFactor ) || 1 ) );

  const deltaRp = safeIp - safeOop;
  const spread = calcSpread( deltaRp );

  // === 1. ESPERANCA MATEMATICA (Custo Direto) ===
  // O RP age como um imposto linear sobre a equidade.
  const esperancaPenaltyOop = safeOop;
  const esperancaPenaltyIp = safeIp;

  // === 2. EXPECTATIVA MATEMATICA (FGS + RIO) ===
  // OOP joga no escuro. As RIO o punem quadraticamente. O passivo estrutural cresce (N-1)^2.
  const opponents = Math.max( 1, activePlayers - 1 );
  const multiwayMultiplier = Math.pow( opponents, 2 );
  const rioPenaltyOop = Math.pow( safeOop / 10, 2 ) * multiwayMultiplier;
  // IP tem controle de pote, RIO e amortecido (escala linear).
  const rioPenaltyIp = ( safeIp / 10 ) * multiwayMultiplier;

  // === 3. PERSPECTIVA MATEMATICA (Distorcao Total) ===
  const pmEvPenaltyOop = esperancaPenaltyOop + rioPenaltyOop;
  const pmEvPenaltyIp = esperancaPenaltyIp + rioPenaltyIp;

  // --- APLICACAO: DEFENSOR (OOP) ---
  // O Call absorve o impacto frontal da Perspectiva.
  const rawCall = Math.max( 0, chipEvFreqs.oop_call - pmEvPenaltyOop );

  // O Raise sofre pressao estrutural, mas ganha sobrevida se o IP estiver mais pressionado (Risk Advantage).
  const raiseDefense = deltaRp > 0 ? ( deltaRp * 0.4 ) : 0;
  const rawRaise = Math.max( 0, chipEvFreqs.oop_raise - pmEvPenaltyOop + raiseDefense );

  const rawRaiseModulated = rawRaise * safeFactor;
  const rawCallClamped = rawCall; // Call nao reage a aggressionFactor (e passivo)
  const rawFoldModulated = Math.max( 0, 100 - rawCallClamped - rawRaiseModulated );

  const oopSum = rawRaiseModulated + rawCallClamped + rawFoldModulated;
  const raiseCenter = oopSum > 0 ? ( rawRaiseModulated / oopSum ) * 100 : 0;
  const callCenter = oopSum > 0 ? ( rawCallClamped / oopSum ) * 100 : 0;
  const foldCenter = Math.max( 0, 100 - callCenter - raiseCenter );

  const oopCall: FreqResult = { center: callCenter, spread, delta: callCenter - chipEvFreqs.oop_call };
  const oopFold: FreqResult = { center: foldCenter, spread, delta: foldCenter - chipEvFreqs.oop_fold };
  const oopRaise: FreqResult = { center: raiseCenter, spread, delta: raiseCenter - chipEvFreqs.oop_raise };

  // --- APLICACAO: AGRESSOR (IP) ---
  // Bet Large infla o pote e aciona a penalizacao RIO de forma agressiva (1.5x).
  const rawBetLarge = Math.max( 0, chipEvFreqs.ip_bet_large - ( pmEvPenaltyIp * 1.5 ) );
  // Bet Small retem o controle SPR, sofrendo menos atrito (0.5x).
  const rawBetSmall = Math.max( 0, chipEvFreqs.ip_bet_small - ( pmEvPenaltyIp * 0.5 ) );

  const rawSmallModulated = rawBetSmall * safeFactor;
  const rawLargeModulated = rawBetLarge * safeFactor;
  const rawCheckModulated = Math.max( 0, 100 - rawSmallModulated - rawLargeModulated );

  const ipSum = rawSmallModulated + rawLargeModulated + rawCheckModulated;
  const betSmallCenter = ipSum > 0 ? ( rawSmallModulated / ipSum ) * 100 : 0;
  const betLargeCenter = ipSum > 0 ? ( rawLargeModulated / ipSum ) * 100 : 0;
  const checkCenter = Math.max( 0, 100 - betSmallCenter - betLargeCenter );

  const ipCheck: FreqResult = { center: checkCenter, spread, delta: checkCenter - chipEvFreqs.ip_check };
  const ipBetSmall: FreqResult = { center: betSmallCenter, spread, delta: betSmallCenter - chipEvFreqs.ip_bet_small };
  const ipBetLarge: FreqResult = { center: betLargeCenter, spread, delta: betLargeCenter - chipEvFreqs.ip_bet_large };

  return {
    ip: { check: ipCheck, bet_small: ipBetSmall, bet_large: ipBetLarge },
    oop: { call: oopCall, fold: oopFold, raise: oopRaise },
    deltaRp,
    bExponent: 1, // Desativado. Mantido fixo para nao quebrar contratos de UI na aba Teoria.
    rawData: { ipRp: safeIp, oopRp: safeOop, chipEvFreqs },
  };
}

import { calculateMapaICM } from './perspectiva';

/**
 * IDENTITY: Motor Algorítmico ICM
 * PATH: src/lib/icmEngine.ts
 * ROLE: Executar o algoritmo clássico de Malmuth-Harville para cálculo de Equidade em Torneios (ICM).
 *       Isolado de React/UI para permitir testes matemáticos puros e máxima performance.
 * BINDING: [src/components/ICMCalculator.tsx] (Alimenta o estado da Interface Visual)
 * TELEOLOGY: Evoluir como motor base para suportar simulações FGS (Future Game Simulation) e cálculos de colisão de ranges baseados em dados massivos (MDA).
 */

export interface ICMPlayer {
  id: string;
  name: string;
  stack: number;
}

export interface ICMResult {
  id: string;
  name: string;
  equity: number;       // Valor financeiro absoluto ($)
  equityPercent: number; // Porcentagem do Prize Pool total (%)
  winProb: number;      // Probabilidade de 1º lugar (0-1)
}

/**
 * Calcula a equidade exata (ICM) baseada no Algoritmo de Malmuth-Harville.
 * [SOTA v3.2]: Delegado para o motor ultra-otimizado O(2^N) do `perspectiva.ts`
 * para garantir Economia de Shannon e evitar a explosao combinatoria O(N!).
 */
export function calculateMalmuthHarville (
  players: ICMPlayer[],
  prizes: number[],
  totalPool?: number,
): ICMResult[] {
  const totalPrizePool = prizes.reduce( ( sum, p ) => sum + p, 0 );
  const denominatorForPercent = totalPool != null && totalPool > 0 ? totalPool : totalPrizePool;

  // Edge case: Sem fichas ou sem premios
  if ( players.length === 0 || totalPrizePool === 0 )
  {
    return players.map( p => ( {
      id: p.id,
      name: p.name,
      equity: 0,
      equityPercent: 0,
      winProb: 0
    } ) );
  }

  // SOTA: Barreira Termodinâmica (Fail-Fast) contra Starvation de CPU e OOM.
  // Para N > 10, o motor reverte graciosamente para ChipEV, garantindo Fricção Zero na UI.
  if ( players.length > 10 )
  {
    // Nota: O valor de N (players.length) deve representar o número de jogadores na mesa.
    // Se N for inesperadamente alto (ex: 3013 como visto em logs), isso pode indicar um problema
    // na fonte de dados que popula o array 'players' ou um uso indevido da função para cenários
    // que não sejam de mesa final de torneio. A função deliberadamente reverte para ChipEV neste caso.
    console.warn( `[ICM Engine] N=${players.length} excede o limite termodinâmico seguro. Revertendo para ChipEV.` );
    const totalChips = players.reduce( ( sum, p ) => sum + p.stack, 0 );
    return players.map( p => {
      const chipPct = totalChips > 0 ? p.stack / totalChips : 0;
      const eq = chipPct * totalPrizePool;
      return {
        id: p.id,
        name: p.name,
        equity: eq,
        equityPercent: denominatorForPercent > 0 ? ( eq / denominatorForPercent ) * 100 : 0,
        winProb: chipPct // Em ChipEV, a probabilidade de cravada é estritamente proporcional ao stack
      };
    } );
  }

  // SOTA: Extrai os stacks e repassa para a engine ultra-rapida c/ memoizacao
  const stacks = players.map( p => p.stack );
  const mapaResult = calculateMapaICM( stacks, prizes );

  // Formata o resultado de saida com as equities calculadas via memoizacao
  return players.map( ( p, i ) => {
    const eq = mapaResult.equities[ i ] || 0;
    const winP = mapaResult.positionProbs[ i ]?.[ 0 ] ?? 0;
    return {
      id: p.id,
      name: p.name,
      equity: eq,
      equityPercent: denominatorForPercent > 0 ? ( eq / denominatorForPercent ) * 100 : 0,
      winProb: winP
    };
  } );
}

