    const ssStack = physics.villain1Stack;
    const setSsStack = (val: number) => updatePhysics({ villain1Stack: val });
    const msStack = physics.villain2Stack;
    const setMsStack = (val: number) => updatePhysics({ villain2Stack: val });
    const edgeFactor = physics.edgeFactor;
    const setEdgeFactor = (val: number) => updatePhysics({ edgeFactor: val });

    const [equity, setEquity] = useState(58); // CL's equity vs SS range

    const {
        potToWin,
        costToCall,
        chipEv,
        clStackWin,
        clStackLoss,
        ssStackWin,
        msEvWin,
        msEvLoss,
        msEvFold,
        futureEvWin,
        futureEvLoss,
        netFutureEv,
        foldFutureEv,
        decision,
        chartData,
        breakEvenEquity,
    } = useMemo(() => {
        const bb = 1;
        const prizes = [0.5, 0.3, 0.2]; // Standard 3-handed prize structure: 50% / 30% / 20%
        const costToCall = ssStack - bb;
        const potToWin = ssStack + bb;

        // ChipEV Calculation
        const evWin = (equity / 100) * potToWin;
        const evLoss = ((100 - equity) / 100) * -costToCall;
        const chipEv = evWin + evLoss;

        // Future State Stacks
        const clStackWin = clStack + ssStack;
        const clStackLoss = clStack - ssStack;
        const ssStackWin = ssStack * 2;

        // Future EV (FGS) Model - SOTA VITOI Paradigm
        const clEdgeAmortizedWin = getAmortizedEdge(clStackWin, msStack, edgeFactor);
        const clEdgeAmortizedLoss = getAmortizedEdge(clStackLoss, ssStackWin, edgeFactor);
        const clEdgeAmortizedFold = getAmortizedEdge(clStack - bb, msStack, edgeFactor);

        // Scenario 1: CL wins, SS is eliminated.
        const baseFutureEvWin = getIcmEquity(clStackWin, msStack, 0, prizes);
        // Scenario 2: CL loses, SS doubles up.
        const baseFutureEvLoss = getIcmEquity(clStackLoss, ssStackWin, msStack, prizes);

        const futureEvWinVal = baseFutureEvWin * clEdgeAmortizedWin;
        const futureEvLossVal = baseFutureEvLoss * clEdgeAmortizedLoss;

        const netFutureEv = (equity / 100) * futureEvWinVal + ((100 - equity) / 100) * futureEvLossVal;
        
        // Scenario 3: CL folds (Monopoly Maintenance Tax risk: MS might eliminate SS)
        const msEliminatesSsProb = 0.35; // Probabilidade do MS eliminar o SS se o CL foldar
        const foldEvIfMsWins = getIcmEquity(clStack - bb, 0, msStack + ssStack + bb, prizes);
        const foldEvIfMsFolds = getIcmEquity(clStack - bb, ssStack + 1.5 * bb, msStack - 0.5 * bb, prizes); // Pote vai para SS (walk ou fold geral)
        
        const baseFoldFutureEv = (msEliminatesSsProb * foldEvIfMsWins) + ((1 - msEliminatesSsProb) * foldEvIfMsFolds);
        const foldFutureEv = baseFoldFutureEv * clEdgeAmortizedFold;

        // Middle Stack EV Impact
        const msEvWin = getIcmEquity(msStack, clStackWin, 0, prizes); // SS busts
