// Subcomponente para renderizar a etapa ativa (Erradicando Complexidade Ciclomatica SOTA)
function ActiveScenarioStep( {
    scenario,
    currentStep,
    selectedChoice,
    isAnswered,
    isRevealing,
    choiceData,
    onSelect
}: {
    readonly scenario: Scenario;
    readonly currentStep: number;
    readonly selectedChoice: string | null;
    readonly isAnswered: boolean;
    readonly isRevealing: boolean;
    readonly choiceData: Choice | undefined;
    readonly onSelect: ( choiceId: string ) => void;
} ) {
    return (
        <motion.div
            key={ currentStep }
            initial={ { opacity: 0, x: 15 } }
            animate={ { opacity: 1, x: 0 } }
            exit={ { opacity: 0, x: -15 } }
            transition={ { duration: 0.25, ease: "easeInOut" } }
        >
            {/* Área do Cenário */ }
            <div style={ { marginBottom: '2rem' } }>
                <h3 style={ { fontSize: '1.1rem', color: 'var(--accent-indigo-light)', marginBottom: '0.75rem', fontWeight: 700 } }>
                    { scenario.title }
                </h3>
                <p style={ { color: 'var(--text-muted)', fontSize: '0.95rem', lineHeight: 1.6, marginBottom: '1rem' } }>
                    { scenario.context }
                </p>
                <div style={ { background: 'rgba(239,68,68,0.1)', borderLeft: '3px solid var(--accent-danger)', padding: '0.75rem 1rem', borderRadius: '4px' } }>
                    <span style={ { fontSize: '0.8rem', fontWeight: 800, color: 'var(--accent-danger-light)', textTransform: 'uppercase' } }>⚠ Armadilha Cognitiva: </span>
                    <span style={ { fontSize: '0.85rem', color: 'var(--text-light)' } }>{ scenario.trap }</span>
                </div>
            </div>

            {/* Opções de Decisão */ }
            <div style={ { display: 'flex', flexDirection: 'column', gap: '0.75rem' } }>
                { scenario.choices.map( choice => {
                    const isSelected = selectedChoice === choice.id;
                    return (
                        <button
                            key={ choice.id }
                            onClick={ () => onSelect( choice.id ) }
                            disabled={ isAnswered || isRevealing }
                            style={ {
                                padding: '1rem', textAlign: 'left', borderRadius: '8px', cursor: ( isAnswered || isRevealing ) ? 'default' : 'pointer',
                                background: getChoiceBackground( isSelected, choice.isCorrect ),
                                border: getChoiceBorder( isSelected, choice.isCorrect ),
                                transition: 'all 0.2s ease',
                                opacity: isAnswered && !isSelected ? 0.4 : 1
                            } }
                        >
                            <span style={ { fontWeight: 700, color: getChoiceColor( isSelected, choice.isCorrect ), fontSize: '0.95rem' } }>
                                { choice.label }
                            </span>
                        </button>
                    );
                } ) }
            </div>

            {/* Painel de Resolução (Impacto Visceral) */ }
            { isRevealing && (
                <motion.div initial={ { opacity: 0 } } animate={ { opacity: 1 } } style={ { marginTop: '2rem', padding: '1.5rem', textAlign: 'center', background: 'rgba(15,23,42,0.4)', borderRadius: '8px', border: '1px dashed rgba(99,102,241,0.2)' } }>
                    <span style={ { fontSize: '0.75rem', color: 'var(--accent-indigo)', textTransform: 'uppercase', letterSpacing: '0.1em', fontWeight: 700 } }>
                        <i className="fa-solid fa-microchip fa-fade" style={ { marginRight: '8px' } } />
                        { ' ' }Processando Vetores de Perspectiva...
                    </span>
                </motion.div>
            ) }

            { isAnswered && !isRevealing && choiceData && (
                <motion.div
                    initial={ { opacity: 0, y: 10 } } animate={ { opacity: 1, y: 0 } } transition={ { duration: 0.3 } }
                    style={ {
                        marginTop: '2rem', padding: '1.5rem', borderRadius: '8px',
                        background: choiceData.isCorrect ? 'rgba(16,185,129,0.05)' : 'rgba(239,68,68,0.05)',
                        borderTop: `3px solid ${choiceData.isCorrect ? 'var(--accent-emerald)' : 'var(--accent-danger)'}`
                    } }
                >
                    <p style={ { margin: '0 0 1rem', fontSize: '0.95rem', color: 'var(--text-light)', lineHeight: 1.6 } }>
                        { choiceData.feedback }
                    </p>
                    <div style={ { display: 'flex', gap: '2rem', fontFamily: 'monospace', flexWrap: 'wrap' } }>
                        <div>
                            <span style={ { display: 'block', fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase' } }>Expectativa (P)</span>
                            <span style={ { fontSize: '1rem', fontWeight: 800, color: 'var(--accent-indigo-light)' } }>
                                { choiceData.metricImpact.expectativa }
                            </span>
                        </div>
                        <div>
                            <span style={ { display: 'block', fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase' } }>EV_Fold (1ª Ordem)</span>
                            <span style={ { fontSize: '1rem', fontWeight: 800, color: 'var(--accent-danger)' } }>
                                { choiceData.metricImpact.evFold }
                            </span>
                        </div>
                        <div>
                            <span style={ { display: 'block', fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase' } }>Perspectiva (PM)</span>
                            <span style={ { fontSize: '1rem', fontWeight: 800, color: choiceData.isCorrect ? 'var(--accent-emerald)' : 'var(--accent-danger)' } }>
                                { choiceData.metricImpact.perspectiva }
                            </span>
                        </div>
                        { choiceData.metricImpact.ci !== undefined && (
                            <div>
                                <span style={ { display: 'block', fontSize: '0.7rem', color: 'var(--text-dim)', textTransform: 'uppercase' } }>Insolvência (Cᵢ)</span>
                                <span style={ { fontSize: '1rem', fontWeight: 800, color: Number( choiceData.metricImpact.ci ) < 1 ? 'var(--accent-danger)' : 'var(--accent-emerald)' } }>
                                    { choiceData.metricImpact.ci }x
                                </span>
                            </div>
                        ) }
                    </div>
                </motion.div>
            ) }
        </motion.div>
    );
}

export default function IcmQuizVisceral() {
    const [scenarios, setScenarios] = useState<Scenario[]>( [] );
    const [currentStep, setCurrentStep] = useState<number>( 0 );
    const [answers, setAnswers] = useState<Record<number, string>>( {} );
    const [isRevealing, setIsRevealing] = useState<boolean>( false );

    useEffect( () => {
        let isMounted = true;

        fetchVisceralScenarios()
            .then( ( data: Scenario[] ) => {
                if ( isMounted ) {
                    setScenarios( data.length > 0 ? data : FALLBACK_SCENARIOS );
                }
            } )
            .catch( ( error: unknown ) => {
                console.warn( "[Quiz] Falha ao sincronizar cenarios:", error );
                if ( isMounted ) setScenarios( FALLBACK_SCENARIOS );
            } );

        return () => { isMounted = false; };
    }, [] );

    if ( scenarios.length === 0 ) {
        return (
            <div style={ { padding: '2rem', textAlign: 'center', color: 'var(--text-dim)', fontStyle: 'italic', letterSpacing: '0.05em' } }>
                <p style={ { textTransform: 'uppercase' } }>Sincronizando Módulo Visceral...</p>
                <div style={ { display: 'flex', gap: '6px', justifyContent: 'center', marginTop: '1rem' } }>
                    <div style={ { width: '6px', height: '6px', borderRadius: '50%', background: 'var(--accent-indigo)', animation: 'pulse 1.5s infinite' } } />
                    <div style={ { width: '6px', height: '6px', borderRadius: '50%', background: 'var(--accent-indigo)', animation: 'pulse 1.5s infinite 0.2s' } } />
                    <div style={ { width: '6px', height: '6px', borderRadius: '50%', background: 'var(--accent-indigo)', animation: 'pulse 1.5s infinite 0.4s' } } />
                </div>
            </div>
        );
    }

    const isFinished = currentStep === scenarios.length;
    const scenario = scenarios[currentStep];
    const selectedChoice = answers[currentStep] || null;
    const isAnswered = selectedChoice !== null;
    const choiceData = scenario?.choices.find( c => c.id === selectedChoice );

    const handleSelect = ( choiceId: string ) => {
        if ( isAnswered || isRevealing ) return;

        setIsRevealing( true );
        setAnswers( prev => ( { ...prev, [currentStep]: choiceId } ) );
        setTimeout( () => setIsRevealing( false ), 850 ); // Micro-delay SOTA
    };

    return (
        <div style={ { maxWidth: '800px', margin: '3rem auto', padding: '2rem', background: 'rgba(15,23,42,0.6)', borderRadius: '12px', border: '1px solid rgba(255,255,255,0.05)' } }>
            <div style={ { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', borderBottom: '1px solid rgba(255,255,255,0.05)', paddingBottom: '1rem' } }>
                <h2 style={ { margin: 0, fontSize: '1.25rem', color: 'var(--text-light)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' } }>
                    Teste Prático: Lente de Perspectiva
                </h2>
                <span style={ { fontSize: '0.85rem', color: 'var(--text-dim)', fontFamily: 'monospace' } }>
                    { isFinished ? 'Síntese Final' : `Cenário 0${currentStep + 1} de 0${scenarios.length}` }
                </span>
            </div>

            <AnimatePresence mode="wait">
                { isFinished ? (
                    <QuizSynthesis onRestart={ () => { setAnswers( {} ); setCurrentStep( 0 ); setIsRevealing( false ); } } />
                ) : (
                    <ActiveScenarioStep
                        scenario={ scenario }
                        currentStep={ currentStep }
                        selectedChoice={ selectedChoice }
                        isAnswered={ isAnswered }
                        isRevealing={ isRevealing }
                        choiceData={ choiceData }
                        onSelect={ handleSelect }
                    />
                ) }
            </AnimatePresence>

            {/* Navegação SOTA */ }
            { !isFinished && (
                <div style={ { display: 'flex', justifyContent: 'space-between', marginTop: '2rem', paddingTop: '1rem', borderTop: '1px solid rgba(255,255,255,0.05)' } }>
                    <button onClick={ () => setCurrentStep( prev => Math.max( 0, prev - 1 ) ) } disabled={ currentStep === 0 } style={ { padding: '0.5rem 1rem', background: 'transparent', color: currentStep === 0 ? 'rgba(255,255,255,0.1)' : 'var(--text-dim)', border: `1px solid ${currentStep === 0 ? 'rgba(255,255,255,0.05)' : 'rgba(255,255,255,0.2)'}`, borderRadius: '6px', cursor: currentStep === 0 ? 'not-allowed' : 'pointer', fontWeight: 600, transition: 'all 0.2s ease' } }>
                        &larr; Voltar
                    </button>
                    <button onClick={ () => setCurrentStep( prev => prev + 1 ) } disabled={ !isAnswered || isRevealing } style={ { padding: '0.5rem 1.5rem', background: ( isAnswered && !isRevealing ) ? 'var(--accent-indigo)' : 'rgba(99,102,241,0.1)', color: ( isAnswered && !isRevealing ) ? '#fff' : 'rgba(255,255,255,0.3)', border: 'none', borderRadius: '6px', cursor: ( isAnswered && !isRevealing ) ? 'pointer' : 'not-allowed', fontWeight: 700, transition: 'all 0.2s ease' } }>
                        { currentStep === scenarios.length - 1 ? 'Ver Síntese' : 'Avançar \u2192' }
                    </button>
                </div>
            ) }
        </div>
    );
}

"use client";

import { useState, useMemo } from "react";
import { calculateRioTension, calculateUtilityEV } from "@/lib/perspectiva";
import { SotaTooltip } from '../ui/SotaTooltip';
import { useSotaSync } from './hooks/useSotaSync';
import
    {
        LineChart,
        Line,
        XAxis,
        YAxis,
        CartesianGrid,
        Tooltip,
        Legend,
        ResponsiveContainer,
        ReferenceLine,
        Label
    } from 'recharts';

export function DownwardDriftSimulator ()
{
    const { physics, updatePhysics, isHydrated } = useSotaSync();
    
    const heroRawStack = physics.heroStack;
    const setHeroRawStack = (val: number) => updatePhysics({ heroStack: val });
    const heroInvested = physics.heroInvested;
    const setHeroInvested = (val: number) => updatePhysics({ heroInvested: val });
    const currentPot = physics.pot;
    const setCurrentPot = (val: number) => updatePhysics({ pot: val });
    const isOop = physics.position === 'OOP';
    const setIsOop = (val: boolean) => updatePhysics({ position: val ? 'OOP' : 'IP' });
    const referenceStatus = physics.referenceStatus;

    const [ baseRioLiability, setBaseRioLiability ] = useState( 15 ); // Base % de RIO

    const { potEntrapment, trueRioTensionIp, trueRioTensionOop, chartData, crossoverPoint } = useMemo( () =>
    {
        const betToCall = currentPot * 0.5;
        const entrapment = ( heroInvested + betToCall ) / Math.max( 0.1, heroRawStack );
        
        const ipTension = calculateRioTension( heroInvested, currentPot, heroRawStack, 'IP', baseRioLiability );
        const oopTension = calculateRioTension( heroInvested, currentPot, heroRawStack, 'OOP', baseRioLiability );

        // Projeção preditiva simulando o aumento do investimento do Hero (Aprisionamento) e Prospect Theory
        const data = [];
        let firstCrossover = null;

        for ( let invested = 0; invested <= heroRawStack; invested += 2 )
        {
            const simIpTension = calculateRioTension( invested, currentPot, heroRawStack, 'IP', baseRioLiability );
            const simOopTension = calculateRioTension( invested, currentPot, heroRawStack, 'OOP', baseRioLiability );
            
            const pctInvested = (invested / heroRawStack) * 100;

            if (firstCrossover === null && simOopTension >= 1) {
                firstCrossover = pctInvested;
            }

            // Exemplo de EV puramente ilustrativo para o gráfico de Prospect Theory
            // Vamos simular a utilidade caindo conforme a tensão aumenta
            const fakeChipEv = 50 - (invested * 1.5); 
            const fakeUtilityEv = calculateUtilityEV(fakeChipEv, referenceStatus);

            data.push( {
                investedPct: Number( pctInvested.toFixed( 0 ) ),
                ipTension: Number( ( simIpTension * 100 ).toFixed( 1 ) ),
                oopTension: Number( ( simOopTension * 100 ).toFixed( 1 ) ),
                chipEv: Number( fakeChipEv.toFixed( 1 ) ),
                utilityEv: Number( fakeUtilityEv.toFixed( 1 ) )
            } );
        }

        return {
            potEntrapment: entrapment,
            trueRioTensionIp: ipTension,
            trueRioTensionOop: oopTension,
            chartData: data,
            crossoverPoint: firstCrossover
        };
    }, [ heroInvested, currentPot, heroRawStack, baseRioLiability, referenceStatus ] );

    const formatPercent = ( value: number ) =>
    {
        return `${ ( value * 100 ).toFixed( 1 ) }%`;
    };

    const activeTension = isOop ? trueRioTensionOop : trueRioTensionIp;

    return (
        <div className="w-full max-w-4xl p-8 mx-auto space-y-8 bg-gray-900 border border-gray-700 rounded-lg shadow-lg">
            <h2 className="text-3xl font-bold text-center text-cyan-400">
                Simulador de Downward Drift & Pot Entrapment
            </h2>

            {/* Controles */ }
            <div className="grid grid-cols-1 gap-8 lg:grid-cols-2">
                <div className="space-y-6">
                    <div>
                        <label htmlFor="heroRawStack" className="block mb-2 text-sm font-medium text-gray-300">
                            Stack do Hero (bb): <span className="font-bold text-white">{ heroRawStack }</span>
                            <SotaTooltip title="Raw Stack" content="Seu stack total antes da mão começar." theme="zinc" />
                        </label>
                        <input
                            id="heroRawStack"
                            type="range"
                            min="10"
                            max="100"
                            step="1"
                            value={ heroRawStack }
                            onChange={ ( e ) => setHeroRawStack( Number( e.target.value ) ) }
                            className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                    <div>
                        <label htmlFor="heroInvested" className="block mb-2 text-sm font-medium text-gray-300">
                            Fichas Investidas: <span className="font-bold text-white">{ heroInvested }</span>
                            <SotaTooltip title="Hero Invested" content="Quanto do seu stack já está no pote (Sunk Cost)." theme="entropy" />
                        </label>
                        <input
                            id="heroInvested"
                            type="range"
                            min="0"
                            max={ heroRawStack }
                            step="1"
                            value={ heroInvested }
                            onChange={ ( e ) => setHeroInvested( Number( e.target.value ) ) }
                            className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                </div>
                <div className="space-y-6">
                    <div>
                        <label htmlFor="currentPot" className="block mb-2 text-sm font-medium text-gray-300">
                            Tamanho do Pote: <span className="font-bold text-white">{ currentPot }</span>
                            <SotaTooltip title="Pote" content="Total de fichas no pote. Define a isca matemática e a proporção da aposta (Bet to Call = 50% do pote no modelo)." theme="zinc" />
                        </label>
                        <input
                            id="currentPot"
                            type="range"
                            min="5"
                            max="200"
                            step="5"
                            value={ currentPot }
                            onChange={ ( e ) => setCurrentPot( Number( e.target.value ) ) }
                            className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer"
                        />
                    </div>
                    <div>
                        <label className="block mb-2 text-sm font-medium text-gray-300">
                            Posição Relativa:
                            <SotaTooltip title="Downward Drift" content="OOP sofre drift de 1.25x na tensão de RIO. IP amortece para 0.85x. Controle espacial altera a matemática da sobrevivência." theme="machine" />
                        </label>
                        <div className="flex gap-4">
                            <button onClick={() => setIsOop(true)} className={`px-4 py-2 text-sm font-bold rounded-lg ${isOop ? 'bg-red-500 text-white' : 'bg-gray-800 text-gray-400'}`}>
                                OOP (Desvantagem)
                            </button>
                            <button onClick={() => setIsOop(false)} className={`px-4 py-2 text-sm font-bold rounded-lg ${!isOop ? 'bg-emerald-500 text-white' : 'bg-gray-800 text-gray-400'}`}>
                                IP (Vantagem)
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Resultados */ }
            <div className="p-6 text-center bg-gray-800 border border-gray-600 rounded-lg">
                <h3 className="mb-4 text-xl font-semibold text-white">Análise de Tensão RIO</h3>

                <div className="grid grid-cols-2 gap-4 mb-6">
                    <div className="p-4 bg-gray-900 border border-gray-700 rounded-lg">
                        <p className="text-sm text-gray-400">Pot Entrapment Ratio</p>
                        <p className="text-3xl font-bold text-orange-400">{ formatPercent( potEntrapment ) }</p>
                    </div>
                    <div className="p-4 bg-gray-900 border border-red-900/50 rounded-lg shadow-[0_0_15px_rgba(220,38,38,0.1)]">
                        <p className="text-sm text-red-400/80">Tensão RIO Real ({isOop ? 'OOP' : 'IP'})</p>
                        <p className={ `text-3xl font-bold ${ activeTension >= 1 ? 'text-red-600' : 'text-red-400' }` }>{ formatPercent( activeTension ) }</p>
                    </div>
                </div>

                <p className="mt-4 text-xs text-gray-500">
                    O <strong>Downward Drift</strong> demonstra como a desvantagem de posição acelera a tensão irrecuperável do RIO. Jogar OOP exige uma proteção severa do range para evitar o colapso estrutural da equidade em stacks medianos.
                </p>
            </div>

            {/* Grafico Recharts */}
            <div className="pt-6 border-t border-gray-700">
                <h3 className="mb-6 text-xl font-semibold text-center text-white">Curva de Aprisionamento (% Stack Investido)</h3>
                <ResponsiveContainer width="100%" height={300}>
                    <LineChart
                        data={chartData}
                        margin={{ top: 5, right: 20, left: -10, bottom: 15 }}
                    >
                        <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                        <XAxis dataKey="investedPct" unit="%" tick={{ fontSize: 12 }} label={{ value: '% do Stack Investido', position: 'insideBottom', offset: -10 }} />
                        <YAxis domain={[0, 100]} tick={{ fontSize: 12 }} />
                        <Tooltip
                            contentStyle={{ backgroundColor: '#222', border: '1px solid #444' }}
                            labelStyle={{ color: '#eee', fontWeight: 'bold' }}
                            formatter={((value: unknown, name: unknown) => [(value as number).toFixed(1) + '%', name]) as never}
                            labelFormatter={(label) => `${label}% Investido`}
                        />
                        <Legend wrapperStyle={{ fontSize: '14px' }} />
                        {crossoverPoint !== null && (
                            <ReferenceLine x={crossoverPoint} stroke="var(--accent-danger)" strokeDasharray="4 4" yAxisId="left">
                                <Label value={`Colapso OOP (${crossoverPoint}%)`} position="insideTopLeft" fill="var(--accent-danger)" fontSize={12} />
                            </ReferenceLine>
                        )}
                        <ReferenceLine y={100} stroke="#ff0000" strokeWidth={1} strokeDasharray="3 3" yAxisId="left" />
                        <Line yAxisId="left" type="monotone" name="Tensão IP (Drift 0.85x)" dataKey="ipTension" stroke="#10b981" strokeWidth={2} dot={false} />
                        <Line yAxisId="left" type="monotone" name="Tensão OOP (Drift 1.25x)" dataKey="oopTension" stroke="#ef4444" strokeWidth={2} dot={false} activeDot={{ r: 6 }} />
                        <Line yAxisId="left" type="monotone" name="ChipEV (Matemático)" dataKey="chipEv" stroke="#0ea5e9" strokeWidth={1} strokeDasharray="5 5" dot={false} />
                        <Line yAxisId="left" type="monotone" name="EV Utilidade (Prospect Theory)" dataKey="utilityEv" stroke="#f59e0b" strokeWidth={2} dot={false} />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>
    );
}

'use client';

/**
 * IDENTITY: Calculadora Malmuth-Harville de Equidade ICM
 * PATH: src/components/simulator/panels/EquityCalculator.tsx
 * ROLE: Inputs manuais de stacks + payouts + hand parser -> cálculo ICM real.
 * BINDING: [lib/icmEngine.ts, lib/handParser.ts, simulator.module.css]
 */

import { useCallback, useMemo, useState } from 'react';
import { parseHandHistory } from '../../../lib/handParser';
import { downloadHRCJson, generateHRCJson } from '../../../lib/hrcExport';
import { calculateMalmuthHarville, type ICMPlayer } from '../../../lib/icmEngine';
import { logger } from '../../../lib/logger';
import AnimatedNumber from '../ui/AnimatedNumber';
import styles from './EquityCalculator.module.css';

// Presets de cenários rápidos
const PRESETS = [
  { label: 'HU (2p)', stacks: [ 50, 50 ], prizes: [ 65, 35 ] },
  { label: '3-Way', stacks: [ 40, 35, 25 ], prizes: [ 50, 30, 20 ] },
  { label: 'FT (6p)', stacks: [ 30, 25, 20, 12, 8, 5 ], prizes: [ 35, 25, 18, 12, 7, 3 ] },
  { label: 'Bolha (4p)', stacks: [ 45, 25, 18, 12 ], prizes: [ 50, 30, 20 ] },
];

export default function EquityCalculator () {
  const [ players, setPlayers ] = useState<ICMPlayer[]>( [
    { id: '1', name: 'Jogador 1', stack: 40 },
    { id: '2', name: 'Jogador 2', stack: 55 },
  ] );
  const [ prizes, setPrizes ] = useState<number[]>( [ 65, 35 ] );
  const [ handText, setHandText ] = useState( '' );
  const [ showParser, setShowParser ] = useState( false );
  const [ parserError, setParserError ] = useState<string | null>( null );
  const [ heroId, setHeroId ] = useState<string | null>( '1' );
  const [ pkoValue, setPkoValue ] = useState( 0 );

  // Cálculo ICM memoizado
  const results = useMemo(
    () => {
      const res = calculateMalmuthHarville( players, prizes );

      // SOTA Audit: Loga métrica de conservação de valor
      const totalEq = res.reduce( ( sum, r ) => sum + r.equityPercent, 0 );
      logger.metric( 'EquityCalculator', 'icm_total_equity', totalEq, { playerCount: players.length } );

      return res;
    },
    [ players, prizes ]
  );

  const totalChips = useMemo(
    () => players.reduce( ( sum, p ) => sum + p.stack, 0 ),
    [ players ]
  );

  const totalPrizes = useMemo(
    () => prizes.reduce( ( sum, p ) => sum + p, 0 ),
    [ prizes ]
  );

  // Exportar para HRC
  const handleExportHRC = useCallback( () => {
    const json = generateHRCJson( players, prizes, pkoValue );
    downloadHRCJson( json, `vitoi_spot_${players.length}p.json` );
  }, [ players, prizes, pkoValue ] );

  // Bubble Factor range: menor e maior BF entre jogadores
  const { bfRange, bfRangeColor } = useMemo( () => {
    if ( results.length < 2 || totalChips === 0 ) return { bfRange: '-', bfRangeColor: 'var(--text-darker)' };
    const bfs = results.map( r => {
      const chip = ( players.find( p => p.id === r.id )?.stack ?? 0 ) / totalChips * 100;
      return chip > 0 ? r.equityPercent / chip : 1;
    } );
    const min = Math.min( ...bfs );
    const max = Math.max( ...bfs );
    let color = 'var(--sim-color-emerald)';
    if ( max > 1.3 )
    {
      color = 'var(--sim-color-rose)';
    } else if ( max > 1.1 )
    {
      color = 'var(--sim-color-amber)';
    }
    return { bfRange: `${min.toFixed( 2 )}-${max.toFixed( 2 )}`, bfRangeColor: color };
  }, [ results, players, totalChips ] );

  // Insight: quem mais ganha/perde com ICM vs proporcional
  const icmInsight = useMemo( () => {
    if ( results.length < 2 || totalChips === 0 ) return null;
    let maxGain = { name: '', delta: -Infinity };
    let maxLoss = { name: '', delta: Infinity };
    for ( const r of results )
    {
      const chip = ( players.find( p => p.id === r.id )?.stack ?? 0 ) / totalChips * 100;
      const delta = r.equityPercent - chip;
      if ( delta > maxGain.delta ) maxGain = { name: r.name, delta };
      if ( delta < maxLoss.delta ) maxLoss = { name: r.name, delta };
    }
    if ( Math.abs( maxGain.delta ) < 0.5 && Math.abs( maxLoss.delta ) < 0.5 )
    {
      return 'Equidade ICM próxima da proporcional — pressão ICM baixa neste spot.';
    }
    return `${maxGain.name} ganha +${maxGain.delta.toFixed( 1 )}% com ICM vs proporcional. ${maxLoss.name} perde ${Math.abs( maxLoss.delta ).toFixed( 1 )}%. Short stacks acumulam equity desproporcional ao risco.`;
  }, [ results, players, totalChips ] );

  // Adicionar jogador
  const addPlayer = useCallback( () => {
    setPlayers( prev => [
      ...prev,
      { id: Date.now().toString(), name: `Jogador ${prev.length + 1}`, stack: 20 },
    ] );
  }, [] );

  // Remover jogador
  const removePlayer = useCallback( ( id: string ) => {
    setPlayers( prev => prev.filter( p => p.id !== id ) );
    if ( heroId === id ) setHeroId( null );
  }, [ heroId ] );

  // Atualizar stack
  const updateStack = useCallback( ( id: string, stack: number ) => {
    setPlayers( prev => prev.map( p => p.id === id ? { ...p, stack } : p ) );
  }, [] );

  // Atualizar nome
  const updateName = useCallback( ( id: string, name: string ) => {
    setPlayers( prev => prev.map( p => p.id === id ? { ...p, name } : p ) );
  }, [] );

  // Atualizar prêmio
  const updatePrize = useCallback( ( idx: number, value: number ) => {
    setPrizes( prev => prev.map( ( p, i ) => i === idx ? value : p ) );
  }, [] );

  // Adicionar prêmio
  const addPrize = useCallback( () => {
    setPrizes( prev => [ ...prev, 10 ] );
  }, [] );

  // Remover prêmio
  const removePrize = useCallback( () => {
    setPrizes( prev => prev.length > 1 ? prev.slice( 0, -1 ) : prev );
  }, [] );

  // Carregar preset
  const loadPreset = useCallback( ( preset: typeof PRESETS[ 0 ] ) => {
    setPlayers(
      preset.stacks.map( ( stack, i ) => ( {
        id: String( i + 1 ),
        name: `Jogador ${i + 1}`,
        stack,
      } ) )
    );
    setPrizes( [ ...preset.prizes ] );
    setHeroId( '1' );
  }, [] );

  // Parse hand history
  const parseHand = useCallback( () => {
    setParserError( null );
    let parsed = parseHandHistory( handText );
    if ( parsed.length >= 2 )
    {
      // SOTA: Limita a captura estritamente à Mesa Final (máx 9 players).
      // Protege o motor Malmuth-Harville de colapso termodinâmico O(N!) caso o usuário cole um lobby dump.
      if ( parsed.length > 9 ) parsed = parsed.slice( 0, 9 );

      setPlayers( parsed );
      setShowParser( false );
      setHandText( '' );
      setHeroId( parsed[ 0 ].id );
    } else
    {
      setParserError( 'Não foi possível identificar pelo menos 2 jogadores. Verifique o formato (ex: "Seat 1: Nome (15000 in chips)").' );
    }
  }, [ handText ] );

  return (
    <div className={ styles.calcPanel }>
      {/* Header */ }
      <div className={ styles.calcHeader }>
        <h3 className={ styles.calcTitle }>
          Calculadora Malmuth-Harville
        </h3>
        <div className={ styles.calcHeaderActions }>
          <button
            onClick={ handleExportHRC }
            className={ styles.calcBtnOutline }
            title="Exportar cenário para HRC JSON"
          >
            <i className="fa-solid fa-file-export" style={ { marginRight: '4px' } } />
            <span>HRC</span>
          </button>
          <button
            onClick={ () => setShowParser( !showParser ) }
            className={ `${styles.calcBtnOutline} ${showParser ? styles.calcBtnOutlineActive : ''}` }
          >
            <i className="fa-solid fa-paste" style={ { marginRight: '4px' } } />
            <span>Parser</span>
          </button>
        </div>
      </div>

      {/* Hand history parser */ }
      { showParser && (
        <div className={ styles.calcParserContainer }>
          <p className={ styles.calcParserLabel }>
            Cole uma hand history (PokerStars / Hand2Note):
          </p>
          <textarea
            value={ handText }
            onChange={ ( e ) => setHandText( e.target.value ) }
            placeholder={ 'Seat 1: Jogador1 (15000 in chips)\nSeat 2: Jogador2 (25000 in chips)' }
            rows={ 4 }
            className={ styles.calcParserTextarea }
          />
          { parserError && (
            <div className={ styles.calcParserError }>
              <i className="fa-solid fa-triangle-exclamation" style={ { marginRight: '6px' } } />
              { parserError }
            </div>
          ) }
          <button
            onClick={ parseHand }
            disabled={ !handText.trim() }
            className={ `${styles.calcParserBtn} ${handText.trim() ? styles.calcParserBtnActive : ''}` }
          >
            Decodificar
          </button>
        </div>
      ) }

      {/* Presets rápidos */ }
      <div className={ styles.calcPresetContainer }>
        { PRESETS.map( ( preset ) => (
          <button
            key={ preset.label }
            onClick={ () => loadPreset( preset ) }
            className={ styles.calcPresetBtn }
          >
            { preset.label }
          </button>
        ) ) }
      </div>

      {/* Grid: Stacks | Payouts */ }
      <div className={ styles.calcGrid2Col }>
        {/* Stacks */ }
        <div className={ styles.calcSection }>
          <h4 className={ styles.calcSectionTitle }>
            Stacks (bb)
          </h4>
          { players.map( ( p ) => (
            <div key={ p.id } className={ styles.calcRow }>
              <button
                type="button"
                onClick={ () => setHeroId( p.id ) }
                style={ {
                  cursor: 'pointer',
                  color: heroId === p.id ? 'var(--accent-indigo)' : 'var(--bg-subtle)',
                  fontSize: '0.65rem',
                  background: 'transparent',
                  border: 'none',
                  padding: 0,
                } }
                title="Definir como Hero"
              >
                <i className={ `fa-solid ${heroId === p.id ? 'fa-circle-user' : 'fa-user'}` } />
              </button>
              <input
                id={ `player-name-${p.id}` }
                name={ `player-name-${p.id}` }
                value={ p.name }
                onChange={ ( e ) => updateName( p.id, e.target.value ) }
                className={ styles.calcInputText }
              />
              <input
                id={ `player-stack-${p.id}` }
                name={ `player-stack-${p.id}` }
                type="number"
                value={ p.stack }
                onChange={ ( e ) => updateStack( p.id, Math.max( 0, Number.parseInt( e.target.value ) || 0 ) ) }
                className={ styles.calcInputNumber }
              />
              { players.length > 2 && (
                <button onClick={ () => removePlayer( p.id ) } className={ styles.calcBtnRemove }>
                  &times;
                </button>
              ) }
            </div>
          ) ) }
          <button onClick={ addPlayer } className={ styles.calcBtnAdd }>
            + Jogador
          </button>
        </div>

        {/* Payouts */ }
        <div className={ styles.calcSection }>
          <h4 className={ styles.calcSectionTitle }>
            Payouts (%)
          </h4>
          { prizes.map( ( prize, idx ) => (
            <div key={ `prize-${idx + 1}-${prize}` } className={ styles.calcRow }>
              <span className={ styles.calcPrizeIndex }>
                { idx + 1 }&ordm;
              </span>
              <input
                id={ `prize-${idx}` }
                name={ `prize-${idx}` }
                type="number"
                value={ prize }
                onChange={ ( e ) => updatePrize( idx, Math.max( 0, Number.parseFloat( e.target.value ) || 0 ) ) }
                className={ styles.calcPrizeInput }
              />
            </div>
          ) ) }
          <div className={ styles.calcBtnPrizeGroup }>
            <button onClick={ addPrize } className={ styles.calcBtnPrizeAdd }>
              + Prêmio
            </button>
            { prizes.length > 1 && (
              <button onClick={ removePrize } className={ styles.calcBtnPrizeRemove }>
                &minus;
              </button>
            ) }
          </div>
        </div>
      </div>

      {/* Resumo */ }
      <div className={ styles.calcStatGrid }>
        { [
          { label: 'Jogadores', value: String( players.length ), color: 'var(--sim-text-main)' },
          { label: 'Fichas', value: String( totalChips ), color: 'var(--sim-color-indigo-light)' },
          { label: 'Pool', value: `${totalPrizes.toFixed( 1 )}%`, color: 'var(--sim-color-emerald)' },
          { label: 'BF Range', value: bfRange, color: bfRangeColor },
        ].map( ( stat ) => (
          <div key={ stat.label } className={ styles.calcStatCard }>
            <div className={ styles.calcStatLabel }>
              { stat.label }
            </div>
            <div className={ styles.calcStatValue } style={ { color: stat.color } }>
              { stat.value }
            </div>
          </div>
        ) ) }
      </div>

      {/* PKO Bounty Slider */ }
      <div style={ {
        background: pkoValue > 0 ? 'rgba(245, 158, 11, 0.05)' : 'rgba(15, 23, 42, 0.4)',
        border: pkoValue > 0 ? '1px solid rgba(245, 158, 11, 0.2)' : '1px solid rgba(255, 255, 255, 0.05)',
        borderRadius: '12px',
        padding: '0.85rem 1.25rem',
      } }>
        <div style={ { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.4rem' } }>
          <span style={ { fontSize: '0.58rem', fontWeight: 900, color: pkoValue > 0 ? 'var(--accent-amber)' : 'var(--text-dim)', textTransform: 'uppercase', letterSpacing: '0.1em' } }>
            PKO Bounty Weight
          </span>
          <span className={ styles.dataMono } style={ { fontSize: '0.75rem', fontWeight: 800, color: pkoValue > 0 ? 'var(--accent-amber)' : 'var(--text-darker)' } }>
            { pkoValue === 0 ? 'OFF' : `${Math.round( pkoValue * 100 )}%` }
          </span>
        </div>
        <input
          type="range"
          min="0"
          max="0.8"
          step="0.05"
          value={ pkoValue }
          onChange={ ( e ) => setPkoValue( Number.parseFloat( e.target.value ) ) }
          style={ { width: '100%', accentColor: 'var(--accent-amber)', cursor: 'pointer' } }
        />
        <p style={ { margin: '0.4rem 0 0', fontSize: '0.55rem', color: 'var(--text-darker)', lineHeight: 1.4 } }>
          Reduz o peso do Prize Pool (ICM) e aumenta o peso da Probabilidade de Vitória (Bounty Pool).
        </p>
      </div>

      {/* Resultados */ }
      <div className={ styles.calcResultPanel }>
        <h4 className={ styles.calcResultTitle }>
          { pkoValue > 0 ? 'Equidade Ajustada (ICM + PKO)' : 'Equidade ICM' }
        </h4>
        { results.map( ( r ) => {
          const chipPercent = totalChips > 0
            ? ( ( players.find( p => p.id === r.id )?.stack ?? 0 ) / totalChips ) * 100
            : 0;

          // Cálculo PKO simplificado: blend entre ICM e WinProb baseado no pkoValue
          const equityPKO = pkoValue > 0
            ? ( 1 - pkoValue ) * r.equityPercent + pkoValue * ( r.winProb * 100 )
            : r.equityPercent;

          const delta = equityPKO - chipPercent;
          let deltaClass = styles.calcResultDeltaNeu;
          if ( delta > 0.5 )
          {
            deltaClass = styles.calcResultDeltaPos;
          } else if ( delta < -0.5 )
          {
            deltaClass = styles.calcResultDeltaNeg;
          }
          const deltaSign = delta > 0 ? '+' : '';
          const isHero = r.id === heroId;

          return (
            <div key={ r.id } className={ styles.calcResultRow }>
              <div className={ styles.calcResultHeader }>
                <span className={ styles.calcResultName }>
                  { isHero && <span className={ styles.calcHeroBadge }>Hero</span> }
                  { r.name }
                </span>
                <div className={ styles.calcResultValues }>
                  { pkoValue > 0 && (
                    <span className={ styles.dataMono } style={ { fontSize: '0.58rem', color: 'var(--accent-amber)', fontWeight: 700, marginRight: '4px' } } title="Win Prob (Bounty Weight)">
                      W: { ( r.winProb * 100 ).toFixed( 1 ) }%
                    </span>
                  ) }
                  <span className={ styles.calcResultChips }>
                    { chipPercent.toFixed( 1 ) }% chips
                  </span>
                  <span className={ styles.calcResultEquity }>
                    <AnimatedNumber value={ equityPKO } suffix="%" />
                  </span>
                  <span className={ `${styles.calcResultDelta} ${deltaClass}` }>
                    { deltaSign }{ delta.toFixed( 1 ) }%
                  </span>
                </div>
              </div>
              {/* Barras: cinza = fichas, indigo = ICM/PKO */ }
              <div className={ styles.calcResultBarContainer }>
                <div
                  className={ styles.calcResultBarChips }
                  style={ { width: `${chipPercent}%` } }
                />
                <div
                  className={ styles.calcResultBarEquity }
                  style={ {
                    width: `${equityPKO}%`,
